(function () {
    'use strict';

    // Синхронизация разборов тренажёра с финальной печатной тетрадью ОГЭ 1–5.
    // Файл подключается ПОСЛЕ practice_scenario_overrides.js, чтобы итоговые решения
    // в каталоге и совпадающих сюжетах были единообразными.
    const FINAL_SOLUTIONS = {"tropinki":{"1.1":"<p>Марусино находится в точке поворота двух шоссе — это 3. Из Куровки к\nВятскому идёт тропинка мимо пруда, поэтому Куровка — 1. Тогда Лягушкино\n— 4, Вятское — 2.</p><p><strong>Ответ: 421</strong></p>","1.2":"<p>Марусино — точка 3, где шоссе поворачивает под прямым углом. Вятское\n— верхняя точка 2. Куровка — точка 1, откуда начинается тропинка мимо\nпруда.</p><p><strong>Ответ: 321</strong></p>","2.1":"<p>От Лягушкино до Марусино по горизонтальному шоссе 15 км, от Марусино\nдо Вятского по вертикальному шоссе 8 км. Всего 15+8=23 км.</p><p><strong>Ответ: 23</strong></p>","2.2":"<p>От Куровки до Марусино 6 км, от Марусино до Вятского 8 км. Получаем\n6+8=14 км.</p><p><strong>Ответ: 14</strong></p>","3.1":"<p>Катеты прямоугольного треугольника равны 15 км и 8 км. По теореме\nПифагора:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mrow><msup><mn>15</mn><mn>2</mn></msup><mo>+</mo><msup><mn>8</mn><mn>2</mn></msup></mrow></msqrt><mo>=</mo><msqrt><mn>289</mn></msqrt><mo>=</mo><mn>17</mn></mrow><annotation encoding=\"application/x-tex\">\\sqrt{15^2+8^2}=\\sqrt{289}=17</annotation></semantics></math>\nкм.</p><p><strong>Ответ: 17</strong></p>","3.2":"<p>Катеты равны 6 км и 8 км. По теореме Пифагора:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mrow><msup><mn>6</mn><mn>2</mn></msup><mo>+</mo><msup><mn>8</mn><mn>2</mn></msup></mrow></msqrt><mo>=</mo><msqrt><mn>100</mn></msqrt><mo>=</mo><mn>10</mn></mrow><annotation encoding=\"application/x-tex\">\\sqrt{6^2+8^2}=\\sqrt{100}=10</annotation></semantics></math>\nкм.</p><p><strong>Ответ: 10</strong></p>","4.1":"<p>Весь маршрут проходит по шоссе и имеет длину 23 км. Время равно\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mfrac><mn>23</mn><mn>25</mn></mfrac><annotation encoding=\"application/x-tex\">\\frac{23}{25}</annotation></semantics></math>\nчаса. Переводим в минуты:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>23</mn><mn>25</mn></mfrac><mo>⋅</mo><mn>60</mn></mrow><annotation encoding=\"application/x-tex\">\\frac{23}{25}\\cdot60</annotation></semantics></math>=55,2\nминуты.</p><p><strong>Ответ: 55,2</strong></p>","4.2":"<p>По шоссе от Лягушкино до Куровки 9 км:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>9</mn><mn>25</mn></mfrac><mo>⋅</mo><mn>60</mn></mrow><annotation encoding=\"application/x-tex\">\\frac{9}{25}\\cdot60</annotation></semantics></math>=21,6\nминуты. Тропинка Куровка–Вятское имеет длину 10 км:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>10</mn><mn>15</mn></mfrac><mo>⋅</mo><mn>60</mn></mrow><annotation encoding=\"application/x-tex\">\\frac{10}{15}\\cdot60</annotation></semantics></math>=40\nминут. Всего 61,6 минуты.</p><p><strong>Ответ: 61,6</strong></p>","5.1":"<p>Стоимость набора в четырёх магазинах: 846 руб., 829 руб., 831 руб. и\n926 руб. Минимальная сумма — 829 руб.</p><p><strong>Ответ: 829</strong></p>","5.2":"<p>Стоимость набора в четырёх магазинах: 1376 руб., 1390 руб., 1316 руб.\nи 1564 руб. Минимальная сумма — 1316 руб.</p><p><strong>Ответ: 1316</strong></p>"},"tariff":{"1.1":"<p><strong>1)</strong> По графику находим месяцы для значений: <strong>1\nГБ → 7-й месяц</strong>; <strong>3 ГБ → 6-й месяц</strong>; <strong>3,25\nГБ → 10-й месяц</strong>; <strong>1,5 ГБ → 8-й месяц</strong>.</p><p><strong>2)</strong> Записываем номера месяцев подряд в заданном\nпорядке: <strong>76108</strong>.</p><p><strong>Ответ: 76108</strong></p>","1.2":"<p><strong>1)</strong> По графику находим месяцы для значений:\n<strong>1,5 ГБ → 8-й месяц</strong>; <strong>2 ГБ → 3-й месяц</strong>;\n<strong>3,75 ГБ → 11-й месяц</strong>; <strong>1 ГБ → 7-й\nмесяц</strong>.</p><p><strong>2)</strong> Записываем номера месяцев подряд в заданном\nпорядке: <strong>83117</strong>.</p><p><strong>Ответ: 83117</strong></p>","1.3":"<p><strong>1)</strong> По графику находим месяцы для значений: <strong>2\nГБ → 3-й месяц</strong>; <strong>2,25 ГБ → 12-й месяц</strong>;\n<strong>4 ГБ → 4-й месяц</strong>; <strong>3,5 ГБ → 2-й\nмесяц</strong>.</p><p><strong>2)</strong> Записываем номера месяцев подряд в заданном\nпорядке: <strong>31242</strong>.</p><p><strong>Ответ: 31242</strong></p>","1.4":"<p><strong>1)</strong> По графику находим месяцы для значений:\n<strong>150 мин. → 3-й месяц</strong>; <strong>300 мин. → 5-й\nмесяц</strong>; <strong>175 мин. → 1-й месяц</strong>; <strong>375 мин.\n→ 7-й месяц</strong>.</p><p><strong>2)</strong> Записываем номера месяцев подряд в заданном\nпорядке: <strong>3517</strong>.</p><p><strong>Ответ: 3517</strong></p>","1.5":"<p><strong>1)</strong> По графику находим месяцы для значений:\n<strong>175 мин. → 1-й месяц</strong>; <strong>300 мин. → 5-й\nмесяц</strong>; <strong>275 мин. → 2-й месяц</strong>; <strong>150 мин.\n→ 3-й месяц</strong>.</p><p><strong>2)</strong> Записываем номера месяцев подряд в заданном\nпорядке: <strong>1523</strong>.</p><p><strong>Ответ: 1523</strong></p>","1.6":"<p><strong>1)</strong> По графику находим месяцы для значений:\n<strong>375 мин. → 7-й месяц</strong>; <strong>150 мин. → 3-й\nмесяц</strong>; <strong>275 мин. → 2-й месяц</strong>; <strong>300 мин.\n→ 5-й месяц</strong>.</p><p><strong>2)</strong> Записываем номера месяцев подряд в заданном\nпорядке: <strong>7325</strong>.</p><p><strong>Ответ: 7325</strong></p>","2.1":"<p><strong>1)</strong> В феврале использовано 275 минут и 3,5 ГБ. Минуты\nвходят в пакет полностью, поэтому доплаты за звонки нет.</p><p><strong>2)</strong> Интернет превышен на 0,5 ГБ — это ровно один\nдополнительный пакет стоимостью 90 руб.</p><p><strong>3)</strong> Итого:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>350</mn><mo>+</mo><mn>90</mn><mo>=</mo><mn>440</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">350+90=440\\text{ руб.}</annotation></semantics></math></p><p><strong>Ответ: 440</strong></p>","2.2":"<p><strong>1)</strong> В июне использовано 325 минут и 3 ГБ. Интернет\nвходит в пакет полностью.</p><p><strong>2)</strong> Сверх пакета использовано\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>325</mn><mo>−</mo><mn>300</mn><mo>=</mo><mn>25</mn></mrow><annotation encoding=\"application/x-tex\">325-300=25</annotation></semantics></math>\nминут. Доплата:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>25</mn><mo>⋅</mo><mn>3</mn><mo>=</mo><mn>75</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">25\\cdot3=75\\text{ руб.}</annotation></semantics></math><strong>3)</strong> Итого:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>350</mn><mo>+</mo><mn>75</mn><mo>=</mo><mn>425</mn></mrow><annotation encoding=\"application/x-tex\">350+75=425</annotation></semantics></math>\nруб.</p><p><strong>Ответ: 425</strong></p>","2.3":"<p><strong>1)</strong> В июле использовано 375 минут и 1 ГБ. За интернет\nдоплаты нет.</p><p><strong>2)</strong> Сверх пакета использовано\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>375</mn><mo>−</mo><mn>300</mn><mo>=</mo><mn>75</mn></mrow><annotation encoding=\"application/x-tex\">375-300=75</annotation></semantics></math>\nминут. Доплата:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>75</mn><mo>⋅</mo><mn>3</mn><mo>=</mo><mn>225</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">75\\cdot3=225\\text{ руб.}</annotation></semantics></math><strong>3)</strong> Итого:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>350</mn><mo>+</mo><mn>225</mn><mo>=</mo><mn>575</mn></mrow><annotation encoding=\"application/x-tex\">350+225=575</annotation></semantics></math>\nруб.</p><p><strong>Ответ: 575</strong></p>","2.4":"<p><strong>1)</strong> В августе использовано 325 минут и 1,5 ГБ.\nИнтернет не превышает включённые 3 ГБ.</p><p><strong>2)</strong> Сверх пакета использовано\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>325</mn><mo>−</mo><mn>300</mn><mo>=</mo><mn>25</mn></mrow><annotation encoding=\"application/x-tex\">325-300=25</annotation></semantics></math>\nминут, поэтому доплата равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>25</mn><mo>⋅</mo><mn>3</mn><mo>=</mo><mn>75</mn></mrow><annotation encoding=\"application/x-tex\">25\\cdot3=75</annotation></semantics></math>\nруб.</p><p><strong>3)</strong> Итого:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>350</mn><mo>+</mo><mn>75</mn><mo>=</mo><mn>425</mn></mrow><annotation encoding=\"application/x-tex\">350+75=425</annotation></semantics></math>\nруб.</p><p><strong>Ответ: 425</strong></p>","2.5":"<p><strong>1)</strong> В апреле использовано 350 минут и 4 ГБ.</p><p><strong>2)</strong> За лишние\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>350</mn><mo>−</mo><mn>300</mn><mo>=</mo><mn>50</mn></mrow><annotation encoding=\"application/x-tex\">350-300=50</annotation></semantics></math>\nминут доплата равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>50</mn><mo>⋅</mo><mn>3</mn><mo>=</mo><mn>150</mn></mrow><annotation encoding=\"application/x-tex\">50\\cdot3=150</annotation></semantics></math>\nруб.</p><p><strong>3)</strong> Интернет превышен на 1 ГБ. Пакет имеет объём 0,5\nГБ, значит нужны\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mrow><mn>0</mn><mo>,</mo><mn>5</mn></mrow></mfrac><mo>=</mo><mn>2</mn></mrow><annotation encoding=\"application/x-tex\">\\frac{1}{0{,}5}=2</annotation></semantics></math>\nдополнительных пакета:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2</mn><mo>⋅</mo><mn>90</mn><mo>=</mo><mn>180</mn></mrow><annotation encoding=\"application/x-tex\">2\\cdot90=180</annotation></semantics></math>\nруб.</p><p><strong>4)</strong> Итого:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>350</mn><mo>+</mo><mn>150</mn><mo>+</mo><mn>180</mn><mo>=</mo><mn>680</mn></mrow><annotation encoding=\"application/x-tex\">350+150+180=680</annotation></semantics></math>\nруб.</p><p><strong>Ответ: 680</strong></p>","2.6":"<p><strong>1)</strong> В декабре использовано 350 минут и 2,25 ГБ.\nИнтернет входит в пакет полностью.</p><p><strong>2)</strong> Сверх пакета использовано\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>350</mn><mo>−</mo><mn>300</mn><mo>=</mo><mn>50</mn></mrow><annotation encoding=\"application/x-tex\">350-300=50</annotation></semantics></math>\nминут. Доплата равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>50</mn><mo>⋅</mo><mn>3</mn><mo>=</mo><mn>150</mn></mrow><annotation encoding=\"application/x-tex\">50\\cdot3=150</annotation></semantics></math>\nруб.</p><p><strong>3)</strong> Итого:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>350</mn><mo>+</mo><mn>150</mn><mo>=</mo><mn>500</mn></mrow><annotation encoding=\"application/x-tex\">350+150=500</annotation></semantics></math>\nруб.</p><p><strong>Ответ: 500</strong></p>","3.1":"<p><strong>1)</strong> В тариф включено <strong>3 ГБ</strong>. Ищем на\nграфике месяцы, где пунктирная линия выше 3 ГБ.</p><p><strong>2)</strong> Это февраль (3,5), апрель (4), октябрь (3,25) и\nноябрь (3,75). Всего <strong>4 месяца</strong>.</p><p><strong>Ответ: 4</strong></p>","3.2":"<p><strong>1)</strong> Одновременно должны выполняться два условия:\nминут не больше <strong>300</strong>, интернета не больше <strong>3\nГБ</strong>.</p><p><strong>2)</strong> Оба условия выполняются в январе, марте, мае и\nсентябре.</p><p><strong>3)</strong> Таких месяцев <strong>4</strong>.</p><p><strong>Ответ: 4</strong></p>","3.3":"<p><strong>1)</strong> Смотрим только сплошную линию — она показывает\nминуты.</p><p><strong>2)</strong> Самая низкая точка находится в марте и\nсоответствует <strong>150 минутам</strong>.</p><p><strong>Ответ: 150</strong></p>","3.4":"<p><strong>1)</strong> Смотрим пунктирную линию — интернет-трафик.</p><p><strong>2)</strong> Минимум достигается в июле: <strong>1\nГБ</strong>.</p><p><strong>Ответ: 1</strong></p>","4.1":"<p><strong>1)</strong> В январе использовано 2,5 ГБ, в феврале — 3,5 ГБ.\nПрирост равен\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3</mn><mo>,</mo><mn>5</mn><mo>−</mo><mn>2</mn><mo>,</mo><mn>5</mn><mo>=</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">3{,}5-2{,}5=1</annotation></semantics></math>\nГБ.</p><p><strong>2)</strong> Процент увеличения считаем относительно\nянварского значения:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mrow><mn>2</mn><mo>,</mo><mn>5</mn></mrow></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mn>40</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{1}{2{,}5}\\cdot100\\%=40\\%.</annotation></semantics></math></p><p><strong>Ответ: 40</strong></p>","4.2":"<p><strong>1)</strong> В июле использован 1 ГБ, в августе — 1,5 ГБ.\nПрирост равен\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><mo>,</mo><mn>5</mn><mo>−</mo><mn>1</mn><mo>=</mo><mn>0</mn><mo>,</mo><mn>5</mn></mrow><annotation encoding=\"application/x-tex\">1{,}5-1=0{,}5</annotation></semantics></math>\nГБ.</p><p><strong>2)</strong> Процент увеличения:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mn>0</mn><mo>,</mo><mn>5</mn></mrow><mn>1</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mn>50</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{0{,}5}{1}\\cdot100\\%=50\\%.</annotation></semantics></math></p><p><strong>Ответ: 50</strong></p>","4.3":"<p><strong>1)</strong> Плата выросла на\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>350</mn><mo>−</mo><mn>200</mn><mo>=</mo><mn>150</mn></mrow><annotation encoding=\"application/x-tex\">350-200=150</annotation></semantics></math>\nруб.</p><p><strong>2)</strong> Относительное увеличение считаем от прежней\nплаты:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>150</mn><mn>200</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mfrac><mn>3</mn><mn>4</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mn>75</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{150}{200}\\cdot100\\%=\\frac34\\cdot100\\%=75\\%.</annotation></semantics></math></p><p><strong>Ответ: 75</strong></p>","4.4":"<p><strong>1)</strong> После повышения на 75% новая плата составляет\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>100</mn><mi>%</mi><mo>+</mo><mn>75</mn><mi>%</mi><mo>=</mo><mn>175</mn><mi>%</mi></mrow><annotation encoding=\"application/x-tex\">100\\%+75\\%=175\\%</annotation></semantics></math>\nпрежней, то есть\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><mo>,</mo><mn>75</mn></mrow><annotation encoding=\"application/x-tex\">1{,}75</annotation></semantics></math>\nот неё.</p><p><strong>2)</strong> Поэтому прежняя плата равна\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>350</mn><mrow><mn>1</mn><mo>,</mo><mn>75</mn></mrow></mfrac><mo>=</mo><mn>200</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">\\frac{350}{1{,}75}=200\\text{ руб.}</annotation></semantics></math></p><p><strong>Ответ: 200</strong></p>","4.5":"<p><strong>1)</strong> После снижения на 30% осталось\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>100</mn><mi>%</mi><mo>−</mo><mn>30</mn><mi>%</mi><mo>=</mo><mn>70</mn><mi>%</mi></mrow><annotation encoding=\"application/x-tex\">100\\%-30\\%=70\\%</annotation></semantics></math>\nпрежней платы, то есть\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0</mn><mo>,</mo><mn>7</mn></mrow><annotation encoding=\"application/x-tex\">0{,}7</annotation></semantics></math>\nот неё.</p><p><strong>2)</strong> Прежняя плата:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>350</mn><mrow><mn>0</mn><mo>,</mo><mn>7</mn></mrow></mfrac><mo>=</mo><mn>500</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">\\frac{350}{0{,}7}=500\\text{ руб.}</annotation></semantics></math></p><p><strong>Ответ: 500</strong></p>","4.6":"<p><strong>1)</strong> Увеличение платы равно\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>490</mn><mo>−</mo><mn>350</mn><mo>=</mo><mn>140</mn></mrow><annotation encoding=\"application/x-tex\">490-350=140</annotation></semantics></math>\nруб.</p><p><strong>2)</strong> Процент повышения относительно прежней платы:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>140</mn><mn>350</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mfrac><mn>2</mn><mn>5</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mn>40</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{140}{350}\\cdot100\\%=\\frac25\\cdot100\\%=40\\%.</annotation></semantics></math></p><p><strong>Ответ: 40</strong></p>","5.1":"<p><strong>1)</strong> За год по «Стандартному» абонент в любом случае\nплатит\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>12</mn><mo>⋅</mo><mn>350</mn><mo>=</mo><mn>4200</mn></mrow><annotation encoding=\"application/x-tex\">12\\cdot350=4200</annotation></semantics></math>\nруб. Доплаты по месяцам, где были превышены лимиты, составляют\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>90</mn><mo>+</mo><mn>330</mn><mo>+</mo><mn>75</mn><mo>+</mo><mn>225</mn><mo>+</mo><mn>75</mn><mo>+</mo><mn>90</mn><mo>+</mo><mn>255</mn><mo>+</mo><mn>150</mn><mo>=</mo><mn>1290</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">90+330+75+225+75+90+255+150=1290\\text{ руб.}</annotation></semantics></math>\nПоэтому годовая стоимость старого тарифа равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4200</mn><mo>+</mo><mn>1290</mn><mo>=</mo><mn>5490</mn></mrow><annotation encoding=\"application/x-tex\">4200+1290=5490</annotation></semantics></math>\nруб.</p><p><strong>2)</strong> Чтобы новый тариф был выгоднее, его месячная\nплата\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>a</mi><annotation encoding=\"application/x-tex\">a</annotation></semantics></math>\nдолжна удовлетворять условию\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>12</mn><mi>a</mi><mo>&lt;</mo><mn>5490</mn><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>a</mi><mo>&lt;</mo><mfrac><mn>5490</mn><mn>12</mn></mfrac><mo>=</mo><mn>457</mn><mo>,</mo><mn>5</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">12a&lt;5490,\\qquad a&lt;\\frac{5490}{12}=457{,}5\\text{ руб.}</annotation></semantics></math><strong>3)</strong> У нового тарифа абонентская плата 440 руб. Поскольку\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>440</mn><mo>&lt;</mo><mn>457</mn><mo>,</mo><mn>5</mn></mrow><annotation encoding=\"application/x-tex\">440&lt;457{,}5</annotation></semantics></math>,\nновый тариф дешевле.</p><p><strong>4)</strong> Абонент выберет новый тариф с ежемесячной платой\n<strong>440 руб.</strong>.</p><p><strong>Ответ: 440</strong></p>","5.2":"<p><strong>1)</strong> За год по «Стандартному» абонент в любом случае\nплатит\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>12</mn><mo>⋅</mo><mn>350</mn><mo>=</mo><mn>4200</mn></mrow><annotation encoding=\"application/x-tex\">12\\cdot350=4200</annotation></semantics></math>\nруб. Доплаты по месяцам, где были превышены лимиты, составляют\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>90</mn><mo>+</mo><mn>330</mn><mo>+</mo><mn>75</mn><mo>+</mo><mn>225</mn><mo>+</mo><mn>75</mn><mo>+</mo><mn>90</mn><mo>+</mo><mn>255</mn><mo>+</mo><mn>150</mn><mo>=</mo><mn>1290</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">90+330+75+225+75+90+255+150=1290\\text{ руб.}</annotation></semantics></math>\nПоэтому годовая стоимость старого тарифа равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4200</mn><mo>+</mo><mn>1290</mn><mo>=</mo><mn>5490</mn></mrow><annotation encoding=\"application/x-tex\">4200+1290=5490</annotation></semantics></math>\nруб.</p><p><strong>2)</strong> Чтобы новый тариф был выгоднее, его месячная\nплата\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>a</mi><annotation encoding=\"application/x-tex\">a</annotation></semantics></math>\nдолжна удовлетворять условию\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>12</mn><mi>a</mi><mo>&lt;</mo><mn>5490</mn><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>a</mi><mo>&lt;</mo><mfrac><mn>5490</mn><mn>12</mn></mfrac><mo>=</mo><mn>457</mn><mo>,</mo><mn>5</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">12a&lt;5490,\\qquad a&lt;\\frac{5490}{12}=457{,}5\\text{ руб.}</annotation></semantics></math><strong>3)</strong> У нового тарифа абонентская плата 460 руб. Поскольку\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>460</mn><mo>&gt;</mo><mn>457</mn><mo>,</mo><mn>5</mn></mrow><annotation encoding=\"application/x-tex\">460&gt;457{,}5</annotation></semantics></math>,\nновый тариф невыгоден.</p><p><strong>4)</strong> Абонент останется на «Стандартном» с ежемесячной\nплатой <strong>350 руб.</strong>.</p><p><strong>Ответ: 350</strong></p>","5.3":"<p><strong>1)</strong> За год по «Стандартному» абонент в любом случае\nплатит\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>12</mn><mo>⋅</mo><mn>350</mn><mo>=</mo><mn>4200</mn></mrow><annotation encoding=\"application/x-tex\">12\\cdot350=4200</annotation></semantics></math>\nруб. Доплаты по месяцам, где были превышены лимиты, составляют\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>90</mn><mo>+</mo><mn>330</mn><mo>+</mo><mn>75</mn><mo>+</mo><mn>225</mn><mo>+</mo><mn>75</mn><mo>+</mo><mn>90</mn><mo>+</mo><mn>255</mn><mo>+</mo><mn>150</mn><mo>=</mo><mn>1290</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">90+330+75+225+75+90+255+150=1290\\text{ руб.}</annotation></semantics></math>\nПоэтому годовая стоимость старого тарифа равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4200</mn><mo>+</mo><mn>1290</mn><mo>=</mo><mn>5490</mn></mrow><annotation encoding=\"application/x-tex\">4200+1290=5490</annotation></semantics></math>\nруб.</p><p><strong>2)</strong> Чтобы новый тариф был выгоднее, его месячная\nплата\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>a</mi><annotation encoding=\"application/x-tex\">a</annotation></semantics></math>\nдолжна удовлетворять условию\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>12</mn><mi>a</mi><mo>&lt;</mo><mn>5490</mn><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>a</mi><mo>&lt;</mo><mfrac><mn>5490</mn><mn>12</mn></mfrac><mo>=</mo><mn>457</mn><mo>,</mo><mn>5</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">12a&lt;5490,\\qquad a&lt;\\frac{5490}{12}=457{,}5\\text{ руб.}</annotation></semantics></math><strong>3)</strong> У нового тарифа абонентская плата 430 руб. Поскольку\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>430</mn><mo>&lt;</mo><mn>457</mn><mo>,</mo><mn>5</mn></mrow><annotation encoding=\"application/x-tex\">430&lt;457{,}5</annotation></semantics></math>,\nновый тариф дешевле.</p><p><strong>4)</strong> Абонент выберет новый тариф с ежемесячной платой\n<strong>430 руб.</strong>.</p><p><strong>Ответ: 430</strong></p>","5.4":"<p><strong>1)</strong> За год по «Стандартному» абонент в любом случае\nплатит\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>12</mn><mo>⋅</mo><mn>350</mn><mo>=</mo><mn>4200</mn></mrow><annotation encoding=\"application/x-tex\">12\\cdot350=4200</annotation></semantics></math>\nруб. Доплаты по месяцам, где были превышены лимиты, составляют\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>90</mn><mo>+</mo><mn>330</mn><mo>+</mo><mn>75</mn><mo>+</mo><mn>225</mn><mo>+</mo><mn>75</mn><mo>+</mo><mn>90</mn><mo>+</mo><mn>255</mn><mo>+</mo><mn>150</mn><mo>=</mo><mn>1290</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">90+330+75+225+75+90+255+150=1290\\text{ руб.}</annotation></semantics></math>\nПоэтому годовая стоимость старого тарифа равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4200</mn><mo>+</mo><mn>1290</mn><mo>=</mo><mn>5490</mn></mrow><annotation encoding=\"application/x-tex\">4200+1290=5490</annotation></semantics></math>\nруб.</p><p><strong>2)</strong> Чтобы новый тариф был выгоднее, его месячная\nплата\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>a</mi><annotation encoding=\"application/x-tex\">a</annotation></semantics></math>\nдолжна удовлетворять условию\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>12</mn><mi>a</mi><mo>&lt;</mo><mn>5490</mn><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>a</mi><mo>&lt;</mo><mfrac><mn>5490</mn><mn>12</mn></mfrac><mo>=</mo><mn>457</mn><mo>,</mo><mn>5</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">12a&lt;5490,\\qquad a&lt;\\frac{5490}{12}=457{,}5\\text{ руб.}</annotation></semantics></math><strong>3)</strong> У нового тарифа абонентская плата 470 руб. Поскольку\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>470</mn><mo>&gt;</mo><mn>457</mn><mo>,</mo><mn>5</mn></mrow><annotation encoding=\"application/x-tex\">470&gt;457{,}5</annotation></semantics></math>,\nновый тариф невыгоден.</p><p><strong>4)</strong> Абонент останется на «Стандартном» с ежемесячной\nплатой <strong>350 руб.</strong>.</p><p><strong>Ответ: 350</strong></p>","5.5":"<p><strong>1)</strong> План «0»: <strong>700·1,5=1050 руб.</strong></p><p><strong>2)</strong> План «200»: <strong>204+(700−200)·1,2=204+600=804\nруб.</strong></p><p><strong>3)</strong> План «700»: <strong>672 руб.</strong>, доплаты\nнет.</p><p><strong>4)</strong> Минимальная стоимость — <strong>672\nруб.</strong></p><p><strong>Ответ: 672</strong></p>","5.6":"<p><strong>1)</strong> План «0»: <strong>800·1,1=880 руб.</strong></p><p><strong>2)</strong> План «300»: <strong>290+(800−300)·1,2=290+600=890\nруб.</strong></p><p><strong>3)</strong> План «800»: <strong>930 руб.</strong>.</p><p><strong>4)</strong> Минимальная стоимость — <strong>880\nруб.</strong></p><p><strong>Ответ: 880</strong></p>"},"apartment":{"1.1":"<p>Коридор обозначен цифрой 2. В противоположном конце коридора\nрасположена кладовая — 3. Рядом с ней спальня — 4. Из гостиной можно\nпопасть на кухню, а из кухни — на лоджию, поэтому кухня обозначена\nцифрой 7.</p><p><strong>Ответ: 2347</strong></p>","1.2":"<p>Коридор — 2, кладовая — 3. Самая большая комната — гостиная, она\nобозначена цифрой 6. Кухня находится слева от гостиной и имеет выход на\nлоджию, это 7.</p><p><strong>Ответ: 2376</strong></p>","1.3":"<p>Коридор — 2. Слева от входа находится санузел — 1. Рядом с кладовой\nрасположена спальня — 4. Самая большая комната — гостиная — 6.</p><p><strong>Ответ: 2146</strong></p>","1.4":"<p>Коридор — 2, кладовая в его противоположном конце — 3, рядом с ней\nспальня — 4, а самое большое помещение — гостиная — 6.</p><p><strong>Ответ: 2346</strong></p>","1.5":"<p>Санузел расположен слева от входа — 1. В конце коридора находится\nкладовая — 3, рядом с ней спальня — 4. Гостиная — самое большое\nпомещение — 6.</p><p><strong>Ответ: 1346</strong></p>","2.1":"<p>Площадь гостиной равна 24,96 м². Одна доска покрывает 0,2·0,8=0,16\nм², одна упаковка — 14·0,16=2,24 м². 24,96:2,24≈11,14, поэтому нужно 12\nупаковок.</p><p><strong>Ответ: 12</strong></p>","2.2":"<p>Площадь коридора равна 8,48 м². Одна упаковка покрывает\n8·0,2·0,4=0,64 м². 8,48:0,64=13,25, значит, необходимо 14 упаковок.</p><p><strong>Ответ: 14</strong></p>","2.3":"<p>Площадь спальни равна 15,84 м². Упаковка покрывает 12·0,2·0,8=1,92\nм². 15,84:1,92=8,25, поэтому потребуется 9 упаковок.</p><p><strong>Ответ: 9</strong></p>","2.4":"<p>Площади лоджий равны 7,04 м² и 4,8 м², вместе 11,84 м². Упаковка\nпокрывает 12·0,4·0,4=1,92 м². 11,84:1,92≈6,17, поэтому нужно 7\nупаковок.</p><p><strong>Ответ: 7</strong></p>","2.5":"<p>Площадь коридора равна 8,48 м², площадь покрытия одной упаковки —\n1,92 м². 8,48:1,92≈4,42, поэтому потребуется 5 упаковок.</p><p><strong>Ответ: 5</strong></p>","2.6":"<p>Площадь спальни равна 15,84 м², одна упаковка покрывает 1,92 м².\n15,84:1,92=8,25, значит, нужно 9 упаковок.</p><p><strong>Ответ: 9</strong></p>","2.7":"<p>Площадь кухни равна 14,4 м². Одна упаковка покрывает 1,92 м².\n14,4:1,92=7,5, поэтому нужно 8 упаковок.</p><p><strong>Ответ: 8</strong></p>","2.8":"<p>Площадь санузла равна 2,4 м². Упаковка покрывает 1,92 м².\n2,4:1,92=1,25, поэтому потребуется 2 упаковки.</p><p><strong>Ответ: 2</strong></p>","3.1":"<p>Спальня занимает\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>11</mn><mo>⋅</mo><mn>9</mn><mo>=</mo><mn>99</mn></mrow><annotation encoding=\"application/x-tex\">11\\cdot9=99</annotation></semantics></math>\nклеток. Площадь одной клетки равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0</mn><mo>,</mo><msup><mn>4</mn><mn>2</mn></msup><mo>=</mo><mn>0</mn><mo>,</mo><mn>16</mn></mrow><annotation encoding=\"application/x-tex\">0{,}4^2=0{,}16</annotation></semantics></math>\nм², поэтому\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S</mi><mo>=</mo><mn>99</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>16</mn><mo>=</mo><mn>15</mn><mo>,</mo><mn>84</mn><msup><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> м</mtext></mrow><mn>2</mn></msup><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">S=99\\cdot0{,}16=15{,}84\\text{ м}^2.</annotation></semantics></math></p><p><strong>Ответ: 15,84</strong></p>","3.2":"<p>Санузел занимает 5·3=15 клеток. Площадь клетки равна 0,4²=0,16 м².\nПолучаем 15·0,16=2,4 м².</p><p><strong>Ответ: 2,4</strong></p>","3.3":"<p>Коридор состоит из двух прямоугольников: 5·3 и 19·2 клеток. Всего\n15+38=53 клетки. Площадь равна 53·0,16=8,48 м².</p><p><strong>Ответ: 8,48</strong></p>","3.4":"<p>Большая лоджия занимает 11·4=44 клетки. Её площадь: 44·0,16=7,04\nм².</p><p><strong>Ответ: 7,04</strong></p>","3.5":"<p>Меньшая лоджия занимает 10·3=30 клеток. Площадь: 30·0,16=4,8 м².</p><p><strong>Ответ: 4,8</strong></p>","3.6":"<p>Гостиная имеет размеры 12 клеток на 13 клеток. Её площадь равна\n12·13·0,16=24,96 м².</p><p><strong>Ответ: 24,96</strong></p>","3.7":"<p>Кладовая занимает 4·2=8 клеток. Площадь: 8·0,16=1,28 м².</p><p><strong>Ответ: 1,28</strong></p>","3.8":"<p>Кухня занимает 10·9=90 клеток. Площадь: 90·0,16=14,4 м².</p><p><strong>Ответ: 14,4</strong></p>","4.1":"<p>Площадь каждой клетки одинакова, поэтому множитель\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0</mn><mo>,</mo><mn>16</mn><msup><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> м</mtext></mrow><mn>2</mn></msup></mrow><annotation encoding=\"application/x-tex\">0{,}16\\text{ м}^2</annotation></semantics></math>\nв отношении площадей сокращается. Удобнее сравнивать число клеток.</p><p><strong>1)</strong> Гостиная занимает\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>12</mn><mo>⋅</mo><mn>13</mn><mo>=</mo><mn>156</mn></mrow><annotation encoding=\"application/x-tex\">12\\cdot13=156</annotation></semantics></math>\nклеток, кладовая —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4</mn><mo>⋅</mo><mn>2</mn><mo>=</mo><mn>8</mn></mrow><annotation encoding=\"application/x-tex\">4\\cdot2=8</annotation></semantics></math>\nклеток.</p><p><strong>2)</strong> Процент увеличения:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mn>156</mn><mo>−</mo><mn>8</mn></mrow><mn>8</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mfrac><mn>148</mn><mn>8</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mn>1850</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{156-8}{8}\\cdot100\\%=\\frac{148}{8}\\cdot100\\%=1850\\%.</annotation></semantics></math></p><p><strong>Ответ: 1850</strong></p>","4.2":"<p>Площадь одной клетки одинакова для обоих помещений, поэтому\nпереводить клетки в квадратные метры не нужно: общий множитель\nсократится.</p><p><strong>1)</strong> Кухня занимает\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>10</mn><mo>⋅</mo><mn>9</mn><mo>=</mo><mn>90</mn></mrow><annotation encoding=\"application/x-tex\">10\\cdot9=90</annotation></semantics></math>\nклеток, санузел —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>5</mn><mo>⋅</mo><mn>3</mn><mo>=</mo><mn>15</mn></mrow><annotation encoding=\"application/x-tex\">5\\cdot3=15</annotation></semantics></math>\nклеток.</p><p><strong>2)</strong> Процент увеличения:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mn>90</mn><mo>−</mo><mn>15</mn></mrow><mn>15</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mfrac><mn>75</mn><mn>15</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mn>500</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{90-15}{15}\\cdot100\\%=\\frac{75}{15}\\cdot100\\%=500\\%.</annotation></semantics></math></p><p><strong>Ответ: 500</strong></p>","4.3":"<p>У обоих помещений площадь клетки одна и та же, поэтому при сравнении\nплощадей множитель\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0</mn><mo>,</mo><mn>16</mn></mrow><annotation encoding=\"application/x-tex\">0{,}16</annotation></semantics></math>\nсокращается.</p><p><strong>1)</strong> Спальня занимает\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>11</mn><mo>⋅</mo><mn>9</mn><mo>=</mo><mn>99</mn></mrow><annotation encoding=\"application/x-tex\">11\\cdot9=99</annotation></semantics></math>\nклеток, примыкающая к ней лоджия —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>11</mn><mo>⋅</mo><mn>4</mn><mo>=</mo><mn>44</mn></mrow><annotation encoding=\"application/x-tex\">11\\cdot4=44</annotation></semantics></math>\nклетки.</p><p><strong>2)</strong> Процент увеличения:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mn>99</mn><mo>−</mo><mn>44</mn></mrow><mn>44</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mfrac><mn>55</mn><mn>44</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mn>125</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{99-44}{44}\\cdot100\\%=\\frac{55}{44}\\cdot100\\%=125\\%.</annotation></semantics></math></p><p><strong>Ответ: 125</strong></p>","4.4":"<p>Сравним не площади в квадратных метрах, а число клеток: общий\nмножитель площади одной клетки сократится.</p><p><strong>1)</strong> Санузел занимает\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>5</mn><mo>⋅</mo><mn>3</mn><mo>=</mo><mn>15</mn></mrow><annotation encoding=\"application/x-tex\">5\\cdot3=15</annotation></semantics></math>\nклеток, кладовая —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4</mn><mo>⋅</mo><mn>2</mn><mo>=</mo><mn>8</mn></mrow><annotation encoding=\"application/x-tex\">4\\cdot2=8</annotation></semantics></math>\nклеток.</p><p><strong>2)</strong> Процент увеличения:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mn>15</mn><mo>−</mo><mn>8</mn></mrow><mn>8</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mfrac><mn>7</mn><mn>8</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mn>87</mn><mo>,</mo><mn>5</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{15-8}{8}\\cdot100\\%=\\frac{7}{8}\\cdot100\\%=87{,}5\\%.</annotation></semantics></math></p><p><strong>Ответ: 87,5</strong></p>","4.5":"<p>Поскольку площадь каждой клетки одинакова, достаточно сравнить\nколичество клеток.</p><p><strong>1)</strong> Лоджия кухни занимает\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>10</mn><mo>⋅</mo><mn>3</mn><mo>=</mo><mn>30</mn></mrow><annotation encoding=\"application/x-tex\">10\\cdot3=30</annotation></semantics></math>\nклеток, кладовая —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4</mn><mo>⋅</mo><mn>2</mn><mo>=</mo><mn>8</mn></mrow><annotation encoding=\"application/x-tex\">4\\cdot2=8</annotation></semantics></math>\nклеток.</p><p><strong>2)</strong> Процент увеличения:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mn>30</mn><mo>−</mo><mn>8</mn></mrow><mn>8</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mfrac><mn>22</mn><mn>8</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mn>275</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{30-8}{8}\\cdot100\\%=\\frac{22}{8}\\cdot100\\%=275\\%.</annotation></semantics></math></p><p><strong>Ответ: 275</strong></p>","4.6":"<p>Общий множитель — площадь одной клетки — при сравнении сокращается,\nпоэтому работаем с числом клеток.</p><p><strong>1)</strong> Коридор занимает\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>53</mn><annotation encoding=\"application/x-tex\">53</annotation></semantics></math>\nклетки, кладовая —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4</mn><mo>⋅</mo><mn>2</mn><mo>=</mo><mn>8</mn></mrow><annotation encoding=\"application/x-tex\">4\\cdot2=8</annotation></semantics></math>\nклеток.</p><p><strong>2)</strong> Процент увеличения:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mn>53</mn><mo>−</mo><mn>8</mn></mrow><mn>8</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mfrac><mn>45</mn><mn>8</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mn>562</mn><mo>,</mo><mn>5</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{53-8}{8}\\cdot100\\%=\\frac{45}{8}\\cdot100\\%=562{,}5\\%.</annotation></semantics></math></p><p><strong>Ответ: 562,5</strong></p>","4.7":"<p>Переводить площади в квадратные метры не требуется: площадь клетки в\nчислителе и знаменателе сократится.</p><p><strong>1)</strong> Кухня занимает\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>10</mn><mo>⋅</mo><mn>9</mn><mo>=</mo><mn>90</mn></mrow><annotation encoding=\"application/x-tex\">10\\cdot9=90</annotation></semantics></math>\nклеток, лоджия —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>10</mn><mo>⋅</mo><mn>3</mn><mo>=</mo><mn>30</mn></mrow><annotation encoding=\"application/x-tex\">10\\cdot3=30</annotation></semantics></math>\nклеток.</p><p><strong>2)</strong> Процент увеличения:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mn>90</mn><mo>−</mo><mn>30</mn></mrow><mn>30</mn></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mn>2</mn><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mn>200</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{90-30}{30}\\cdot100\\%=2\\cdot100\\%=200\\%.</annotation></semantics></math></p><p><strong>Ответ: 200</strong></p>","5.1":"<p>Подходят модели А, Е и Ж. Их полная стоимость: А — 28 000+1700=29 700\nруб.; Е — 27 600+2300=29 900 руб.; Ж — 27 585+1900+10%·27 585=32 243,5\nруб. Минимум — 29 700 руб.</p><p><strong>Ответ: 29700</strong></p>","5.2":"<p>План «800»: за месяц 900+(850−800)·2=1000 руб., за 3 месяца — 3000\nруб. План «1000» стоит 3150 руб. за 3 месяца, безлимитный — 3300 руб.\nСамый дешёвый вариант — 3000 руб.</p><p><strong>Ответ: 3000</strong></p>","5.3":"<p>Подходят модели А, Е, Ж и К. Их полная стоимость соответственно 29\n700 руб., 29 900 руб., 32 243,5 руб. и 28 800 руб. Минимальная стоимость\n— 28 800 руб.</p><p><strong>Ответ: 28800</strong></p>","5.4":"<p>Подходят модели Г, Д и З. Полная стоимость: Г — 24 000+4500+2400=30\n900 руб.; Д — 28 000+1700=29 700 руб.; З — 20 000+6300+3000=29 300 руб.\nМинимум — 29 300 руб.</p><p><strong>Ответ: 29300</strong></p>","5.5":"<p>Подходят модели Б, В, З и И. Их полная стоимость: 30 900 руб., 32 500\nруб., 29 300 руб. и 28 800 руб. Самый дешёвый вариант — модель И за 28\n800 руб.</p><p><strong>Ответ: 28800</strong></p>","5.6":"<p>При трафике 650 Мб план «800» стоит 900 руб. в месяц, то есть 2700\nруб. за 3 месяца. Остальные планы дороже.</p><p><strong>Ответ: 2700</strong></p>","5.7":"<p>При трафике 700 Мб достаточно плана «800»: 900·3=2700 руб. План\n«1000» и безлимитный обойдутся дороже.</p><p><strong>Ответ: 2700</strong></p>","5.8":"<p>План «800» стоит за месяц 900+200·2=1300 руб., за 3 месяца 3900 руб.\nПлан «1000» стоит 1050·3=3150 руб., безлимитный — 3300 руб. Минимум —\n3150 руб.</p><p><strong>Ответ: 3150</strong></p>"},"tires":{"1.1":"<p><strong>1)</strong> Смотрим только столбец <strong>18\nдюймов</strong>. В нём разрешены маркировки <strong>235/45</strong> и\n<strong>245/40</strong>.</p><p><strong>2)</strong> Первое число маркировки — ширина шины. Возможные\nширины: 235 мм и 245 мм.</p><p><strong>3)</strong> Меньшая из них равна <strong>235 мм</strong>.</p><p><strong>Ответ: 235</strong></p>","2.1":"<p><strong>1)</strong> В маркировке 225/60 R17 ширина шины\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi><mo>=</mo><mn>225</mn></mrow><annotation encoding=\"application/x-tex\">B=225</annotation></semantics></math>\nмм, а высота боковины равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>60</mn><mi>%</mi></mrow><annotation encoding=\"application/x-tex\">60\\%</annotation></semantics></math>\nширины.</p><p><strong>2)</strong> Сначала сократим процентную дробь:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>H</mi><mo>=</mo><mn>225</mn><mo>⋅</mo><mfrac><mn>60</mn><mn>100</mn></mfrac><mo>=</mo><mn>225</mn><mo>⋅</mo><mfrac><mn>3</mn><mn>5</mn></mfrac><mo>=</mo><mn>45</mn><mo>⋅</mo><mn>3</mn><mo>=</mo><mn>135</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мм</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">H=225\\cdot\\frac{60}{100}=225\\cdot\\frac35=45\\cdot3=135\\text{ мм}.</annotation></semantics></math></p><p><strong>Ответ: 135</strong></p>","3.1":"<p><strong>1)</strong> Для шины 225/55 R16 диаметр диска равен\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>16</mn><mo>⋅</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>=</mo><mn>406</mn><mo>,</mo><mn>4</mn></mrow><annotation encoding=\"application/x-tex\">16\\cdot25{,}4=406{,}4</annotation></semantics></math>\nмм.</p><p><strong>2)</strong> Удобно сразу учесть две одинаковые боковины:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2</mn><mi>H</mi><mo>=</mo><mn>2</mn><mo>⋅</mo><mn>225</mn><mo>⋅</mo><mfrac><mn>55</mn><mn>100</mn></mfrac><mo>=</mo><mn>225</mn><mo>⋅</mo><mfrac><mn>11</mn><mn>10</mn></mfrac><mo>=</mo><mn>247</mn><mo>,</mo><mn>5</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мм</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">2H=2\\cdot225\\cdot\\frac{55}{100}=225\\cdot\\frac{11}{10}=247{,}5\\text{ мм}.</annotation></semantics></math><strong>3)</strong> Диаметр колеса:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D</mi><mo>=</mo><mn>406</mn><mo>,</mo><mn>4</mn><mo>+</mo><mn>247</mn><mo>,</mo><mn>5</mn><mo>=</mo><mn>653</mn><mo>,</mo><mn>9</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мм</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">D=406{,}4+247{,}5=653{,}9\\text{ мм}.</annotation></semantics></math></p><p><strong>Ответ: 653,9</strong></p>","4.1":"<p><strong>1)</strong> Запишем разность диаметров сразу в общем виде, не\nвычисляя каждый диаметр отдельно:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>18</mn><mo>−</mo><mn>16</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>⋅</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>+</mo><mn>2</mn><mo minsize=\"1.2\" maxsize=\"1.2\" stretchy=\"false\" form=\"prefix\">(</mo><mn>235</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>45</mn><mo>−</mo><mn>225</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>55</mn><mo minsize=\"1.2\" maxsize=\"1.2\" stretchy=\"false\" form=\"postfix\">)</mo><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=(18-16)\\cdot25{,}4+2\\bigl(235\\cdot0{,}45-225\\cdot0{,}55\\bigr).</annotation></semantics></math><strong>2)</strong> Упростим выражение до подстановки крупных чисел:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mn>2</mn><mo>⋅</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>+</mo><mn>2</mn><mo minsize=\"1.2\" maxsize=\"1.2\" stretchy=\"false\" form=\"prefix\">(</mo><mn>105</mn><mo>,</mo><mn>75</mn><mo>−</mo><mn>123</mn><mo>,</mo><mn>75</mn><mo minsize=\"1.2\" maxsize=\"1.2\" stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mn>50</mn><mo>,</mo><mn>8</mn><mo>−</mo><mn>36</mn><mo>=</mo><mn>14</mn><mo>,</mo><mn>8</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мм</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=2\\cdot25{,}4+2\\bigl(105{,}75-123{,}75\\bigr)\n=50{,}8-36=14{,}8\\text{ мм}.</annotation></semantics></math> Так\nвычисления короче: общая часть формулы сразу сокращается в разности.</p><p><strong>Ответ: 14,8</strong></p>","5.1":"<p><strong>1)</strong> За один оборот колесо проходит длину окружности\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mi>π</mi><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">L=\\pi D</annotation></semantics></math>.\nПоэтому процентное изменение пробега равно процентному изменению\nдиаметра: множитель\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>π</mi><annotation encoding=\"application/x-tex\">\\pi</annotation></semantics></math>\nсокращается.</p><p><strong>2)</strong> У нового и заводского колеса диаметр диска\nодинаковый — 16 дюймов. Значит, в разности диаметров эта часть сразу\nсокращается:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mn>2</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>55</mn><mspace width=\"0.167em\"></mspace><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>235</mn><mo>−</mo><mn>225</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mn>1</mn><mo>,</mo><mn>1</mn><mo>⋅</mo><mn>10</mn><mo>=</mo><mn>11</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мм</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=2\\cdot0{,}55\\,(235-225)=1{,}1\\cdot10=11\\text{ мм}.</annotation></semantics></math><strong>3)</strong> Для процента нужен исходный диаметр:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D</mi><mn>0</mn></msub><mo>=</mo><mn>16</mn><mo>⋅</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>+</mo><mn>2</mn><mo>⋅</mo><mn>225</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>55</mn><mo>=</mo><mn>653</mn><mo>,</mo><mn>9</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мм</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">D_0=16\\cdot25{,}4+2\\cdot225\\cdot0{,}55=653{,}9\\text{ мм}.</annotation></semantics></math><strong>4)</strong> Тогда\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mi>Δ</mi><mi>D</mi></mrow><msub><mi>D</mi><mn>0</mn></msub></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>=</mo><mfrac><mn>11</mn><mrow><mn>653</mn><mo>,</mo><mn>9</mn></mrow></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>≈</mo><mn>1</mn><mo>,</mo><mn>7</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{\\Delta D}{D_0}\\cdot100\\%=\\frac{11}{653{,}9}\\cdot100\\%\\approx1{,}7\\%.</annotation></semantics></math></p><p><strong>Ответ: 1,7</strong></p>"},"stove":{"1.1":"<p><strong>1)</strong> По таблице масса <strong>15 кг</strong>\nсоответствует электрической печи №<strong>3</strong>.</p><p><strong>2)</strong> Масса <strong>40 кг</strong> соответствует\nдровяной печи №<strong>1</strong>.</p><p><strong>3)</strong> Масса <strong>48 кг</strong> соответствует\nдровяной печи №<strong>2</strong>.</p><p><strong>4)</strong> Записываем номера в указанном порядке:\n<strong>312</strong>.</p><p><strong>Ответ: 312</strong></p>","1.2":"<p><strong>1)</strong> Стоимость <strong>15 000 руб.</strong> указана\nдля печи №<strong>3</strong>.</p><p><strong>2)</strong> Стоимость <strong>19 500 руб.</strong> — для печи\n№<strong>2</strong>.</p><p><strong>3)</strong> Стоимость <strong>18 000 руб.</strong> — для печи\n№<strong>1</strong>.</p><p><strong>Ответ: 321</strong></p>","2.1":"<p><strong>1)</strong> Парное отделение — прямоугольный параллелепипед с\nразмерами <strong>3,5 м × 2,2 м × 2 м</strong>.</p><p><strong>2)</strong> Объём: V=3,5·2,2·2=15,4 м³.</p><p><strong>Ответ: 15,4</strong></p>","2.2":"<p><strong>1)</strong> Пол — прямоугольник размером <strong>3,5 м × 2,2\nм</strong>.</p><p><strong>2)</strong> Площадь пола: S=3,5·2,2=7,7 м².</p><p><strong>Ответ: 7,7</strong></p>","2.3":"<p><strong>1)</strong> Площадь четырёх стен равна периметру пола,\nумноженному на высоту: 2·(3,5+2,2)·2=22,8 м².</p><p><strong>2)</strong> Размер дверного проёма: <strong>0,6 м × 1,8\nм</strong>. Его площадь: 0,6·1,8=1,08 м².</p><p><strong>3)</strong> Искомая площадь: 22,8−1,08=21,72 м².</p><p><strong>Ответ: 21,72</strong></p>","3.1":"<p><strong>1)</strong> Объём парного отделения равен <strong>15,4\nм³</strong>. Из дровяных печей подходит печь №2: её диапазон\n<strong>10–16 м³</strong>, стоимость <strong>19 500 руб.</strong></p><p><strong>2)</strong> Электрическая печь №3 подходит по объёму:\n<strong>9–15,5 м³</strong>. С учётом кабеля она стоит 15 000+6500=21 500\nруб.</p><p><strong>3)</strong> Разница: 21 500−19 500=2000 руб.</p><p><strong>Ответ: 2000</strong></p>","3.2":"<p><strong>1)</strong> По объёму 15,4 м³ подходит дровяная печь №2\nстоимостью <strong>19 500 руб.</strong></p><p><strong>2)</strong> Электрическая печь №3 без учёта установки стоит\n<strong>15 000 руб.</strong></p><p><strong>3)</strong> Разница: 19 500−15 000=4500 руб.</p><p><strong>Ответ: 4500</strong></p>","4.1":"<p><strong>1)</strong> Печь массой 40 кг — это печь №1 стоимостью\n<strong>18 000 руб.</strong></p><p><strong>2)</strong> После скидки\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>10</mn><mi>%</mi></mrow><annotation encoding=\"application/x-tex\">10\\%</annotation></semantics></math>\nостаётся\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>90</mn><mi>%</mi></mrow><annotation encoding=\"application/x-tex\">90\\%</annotation></semantics></math>\nпервоначальной цены, поэтому сразу находим новую стоимость:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>18</mn><mspace width=\"0.167em\"></mspace><mn>000</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>9</mn><mo>=</mo><mn>16</mn><mspace width=\"0.167em\"></mspace><mn>200</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">18\\,000\\cdot0{,}9=16\\,200\\text{ руб.}</annotation></semantics></math></p><p><strong>Ответ: 16200</strong></p>","4.2":"<p><strong>1)</strong> Печь массой 48 кг — печь №2. Её цена <strong>19\n500 руб.</strong></p><p><strong>2)</strong> После скидки 10% остаётся 90% цены: 19 500·0,9=17\n550 руб.</p><p><strong>Ответ: 17550</strong></p>","5.1":"<p><strong>1)</strong> Центр окружности находится в середине нижней\nстороны кожуха. Половина ширины кожуха: 50:2=25 см.</p><p><strong>2)</strong> До точки начала арки по вертикали <strong>60\nсм</strong>. Радиус является гипотенузой прямоугольного треугольника с\nкатетами 25 и 60.</p><p><strong>3)</strong> По теореме Пифагора:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>=</mo><msqrt><mrow><msup><mn>25</mn><mn>2</mn></msup><mo>+</mo><msup><mn>60</mn><mn>2</mn></msup></mrow></msqrt><mo>=</mo><msqrt><mn>4225</mn></msqrt><mo>=</mo><mn>65</mn></mrow><annotation encoding=\"application/x-tex\">R=\\sqrt{25^2+60^2}=\\sqrt{4225}=65</annotation></semantics></math>\nсм.</p><p><strong>Ответ: 65</strong></p>","5.2":"<p><strong>1)</strong> Половина ширины кожуха: 60:2=30 см.</p><p><strong>2)</strong> Вертикальный катет равен <strong>40\nсм</strong>.</p><p><strong>3)</strong> Радиус:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>=</mo><msqrt><mrow><msup><mn>30</mn><mn>2</mn></msup><mo>+</mo><msup><mn>40</mn><mn>2</mn></msup></mrow></msqrt><mo>=</mo><msqrt><mn>2500</mn></msqrt><mo>=</mo><mn>50</mn></mrow><annotation encoding=\"application/x-tex\">R=\\sqrt{30^2+40^2}=\\sqrt{2500}=50</annotation></semantics></math>\nсм.</p><p><strong>Ответ: 50</strong></p>"},"sheets":{"1.1":"<p><strong>1)</strong> Лист <strong>A2</strong> имеет размеры\n<strong>594×420</strong>, значит это номер <strong>2</strong>.</p><p><strong>2)</strong> Лист <strong>A3</strong> имеет размеры\n<strong>420×297</strong>, значит это номер <strong>4</strong>.</p><p><strong>3)</strong> Лист <strong>A5</strong> имеет размеры\n<strong>210×148</strong>, значит это номер <strong>1</strong>.</p><p><strong>4)</strong> Лист <strong>A6</strong> имеет размеры\n<strong>148×105</strong>, значит это номер <strong>3</strong>.</p><p><strong>5)</strong> Записываем ответ в порядке A2, A3, A5, A6:\n<strong>2413</strong>.</p><p><strong>Ответ: 2413</strong></p>","1.2":"<p><strong>1)</strong> A2 — это <strong>594×420</strong>, номер\n<strong>1</strong>.</p><p><strong>2)</strong> A3 — это <strong>420×297</strong>, номер\n<strong>2</strong>.</p><p><strong>3)</strong> A4 — это <strong>297×210</strong>, номер\n<strong>4</strong>.</p><p><strong>4)</strong> A6 — это <strong>148×105</strong>, номер\n<strong>3</strong>.</p><p><strong>Ответ: 1243</strong></p>","1.3":"<p><strong>1)</strong> A0 соответствует размерам\n<strong>1189×841</strong>, это номер <strong>2</strong>.</p><p><strong>2)</strong> A1 соответствует размерам\n<strong>841×594</strong>, это номер <strong>1</strong>.</p><p><strong>3)</strong> A2 соответствует размерам\n<strong>594×420</strong>, это номер <strong>4</strong>.</p><p><strong>4)</strong> A4 соответствует размерам\n<strong>297×210</strong>, это номер <strong>3</strong>.</p><p><strong>Ответ: 2143</strong></p>","1.4":"<p><strong>1)</strong> A0 — <strong>1189×841</strong>, номер\n<strong>3</strong>.</p><p><strong>2)</strong> A2 — <strong>594×420</strong>, номер\n<strong>1</strong>.</p><p><strong>3)</strong> A3 — <strong>420×297</strong>, номер\n<strong>2</strong>.</p><p><strong>4)</strong> A5 — <strong>210×148</strong>, номер\n<strong>4</strong>.</p><p><strong>Ответ: 3124</strong></p>","2.1":"<p><strong>1)</strong> Переход от A2 к A4 — это два последовательных\nразрезания пополам: <strong>A2\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mo>→</mo><annotation encoding=\"application/x-tex\">\\to</annotation></semantics></math>\nA3\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mo>→</mo><annotation encoding=\"application/x-tex\">\\to</annotation></semantics></math>\nA4</strong>.</p><p><strong>2)</strong> При каждом разрезании число листов удваивается,\nпоэтому сразу получаем\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mn>2</mn><mn>2</mn></msup><mo>=</mo><mn>4</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> листа</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">2^2=4\\text{ листа}.</annotation></semantics></math></p><p><strong>Ответ: 4</strong></p>","2.2":"<p><strong>1)</strong> Переход от A1 к A4: <strong>A1 → A2 → A3 →\nA4</strong>.</p><p><strong>2)</strong> Это три последовательных деления пополам, поэтому\nчисло листов увеличивается в\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mn>2</mn><mn>3</mn></msup><mo>=</mo><mn>8</mn></mrow><annotation encoding=\"application/x-tex\">2^{3}=8</annotation></semantics></math>\nраз.</p><p><strong>Ответ: 8</strong></p>","2.3":"<p><strong>1)</strong> Один лист A2 при одном разрезании пополам даёт\nдва листа A3.</p><p><strong>Ответ: 2</strong></p>","2.4":"<p><strong>1)</strong> Переход: <strong>A3 → A4 → A5</strong>.</p><p><strong>2)</strong> Это два деления пополам, значит количество листов\nувеличится в\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mn>2</mn><mn>2</mn></msup><mo>=</mo><mn>4</mn></mrow><annotation encoding=\"application/x-tex\">2^{2}=4</annotation></semantics></math>\nраза.</p><p><strong>Ответ: 4</strong></p>","3.1":"<p><strong>1)</strong> Площадь листа A0 равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><msup><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> м</mtext></mrow><mn>2</mn></msup><mo>=</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn><msup><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> см</mtext></mrow><mn>2</mn></msup></mrow><annotation encoding=\"application/x-tex\">1\\text{ м}^2=10\\,000\\text{ см}^2</annotation></semantics></math>.</p><p><strong>2)</strong> От A0 до A3 — три деления площади пополам,\nпоэтому\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mrow><mi>A</mi><mn>3</mn></mrow></msub><mo>=</mo><mfrac><mrow><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><msup><mn>2</mn><mn>3</mn></msup></mfrac><mo>=</mo><mfrac><mrow><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><mn>8</mn></mfrac><mo>=</mo><mn>1250</mn><msup><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> см</mtext></mrow><mn>2</mn></msup><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">S_{A3}=\\frac{10\\,000}{2^3}=\\frac{10\\,000}{8}=1250\\text{ см}^2.</annotation></semantics></math></p><p><strong>Ответ: 1250</strong></p>","3.2":"<p><strong>1)</strong> Площадь A0 равна <strong>10 000 см²</strong>.</p><p><strong>2)</strong> От A0 до A5 — пять делений пополам.</p><p><strong>3)</strong> Поэтому площадь листа A5 равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn><mo>:</mo><msup><mn>2</mn><mn>5</mn></msup><mo>=</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn><mo>:</mo><mn>32</mn><mo>=</mo><mn>312</mn><mo>,</mo><mn>5</mn></mrow><annotation encoding=\"application/x-tex\">10\\,000 : 2^{5} = 10\\,000 : 32 = 312{,}5</annotation></semantics></math>\nсм².</p><p><strong>Ответ: 312,5</strong></p>","3.3":"<p><strong>1)</strong> Стандартные размеры листа A0: <strong>1189×841\nмм</strong>.</p><p><strong>2)</strong> Ширина — меньшая сторона, то есть <strong>841\nмм</strong>.</p><p><strong>3)</strong> Ближайшее число, кратное 10: <strong>840\nмм</strong>.</p><p><strong>Ответ: 840</strong></p>","3.4":"<p><strong>1)</strong> Стандартные размеры листа A4: <strong>297×210\nмм</strong>.</p><p><strong>2)</strong> Ширина равна <strong>210 мм</strong>. Это уже\nчисло, кратное 10.</p><p><strong>Ответ: 210</strong></p>","3.5":"<p><strong>1)</strong> Размеры листа A1: <strong>841×594\nмм</strong>.</p><p><strong>2)</strong> Длина — большая сторона, то есть <strong>841\nмм</strong>.</p><p><strong>3)</strong> После округления до ближайшего числа, кратного\n10, получаем <strong>840 мм</strong>.</p><p><strong>Ответ: 840</strong></p>","3.6":"<p><strong>1)</strong> Размеры листа A6: <strong>148×105\nмм</strong>.</p><p><strong>2)</strong> Длина — большая сторона, это <strong>148\nмм</strong>.</p><p><strong>3)</strong> Ближайшее число, кратное 10, — <strong>150\nмм</strong>.</p><p><strong>Ответ: 150</strong></p>","4.1":"<p><strong>1)</strong> Размеры листа A4:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>297</mn><mo>×</mo><mn>210</mn></mrow><annotation encoding=\"application/x-tex\">297\\times210</annotation></semantics></math>\nмм.</p><p><strong>2)</strong> Отношение меньшей стороны к большей:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>210</mn><mn>297</mn></mfrac><mo>=</mo><mfrac><mn>70</mn><mn>99</mn></mfrac><mo>≈</mo><mn>0</mn><mo>,</mo><mn>707</mn><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{210}{297}=\\frac{70}{99}\\approx0{,}707.</annotation></semantics></math><strong>3)</strong> Округляя до десятых, получаем\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0</mn><mo>,</mo><mn>7</mn></mrow><annotation encoding=\"application/x-tex\">0{,}7</annotation></semantics></math>.</p><p><strong>Ответ: 0,7</strong></p>","4.2":"<p><strong>1)</strong> Размеры листа A1:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>841</mn><mo>×</mo><mn>594</mn></mrow><annotation encoding=\"application/x-tex\">841\\times594</annotation></semantics></math>\nмм.</p><p><strong>2)</strong> Искомое отношение:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>841</mn><mn>594</mn></mfrac><mo>≈</mo><mn>1</mn><mo>,</mo><mn>416</mn><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{841}{594}\\approx1{,}416.</annotation></semantics></math><strong>3)</strong> Округляя до десятых, получаем\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><mo>,</mo><mn>4</mn></mrow><annotation encoding=\"application/x-tex\">1{,}4</annotation></semantics></math>.</p><p><strong>Ответ: 1,4</strong></p>","5.1":"<p><strong>1)</strong> Площадь одного листа A5 равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><msup><mn>2</mn><mn>5</mn></msup></mfrac><mo>=</mo><mfrac><mn>1</mn><mn>32</mn></mfrac></mrow><annotation encoding=\"application/x-tex\">\\frac{1}{2^5}=\\frac1{32}</annotation></semantics></math>\nм².</p><p><strong>2)</strong> Массу всей пачки удобно найти одной формулой, не\nвычисляя отдельно массу каждого листа:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi><mo>=</mo><mn>80</mn><mo>⋅</mo><mn>500</mn><mo>⋅</mo><mfrac><mn>1</mn><mn>32</mn></mfrac><mo>=</mo><mfrac><mn>80</mn><mn>32</mn></mfrac><mo>⋅</mo><mn>500</mn><mo>=</mo><mn>2</mn><mo>,</mo><mn>5</mn><mo>⋅</mo><mn>500</mn><mo>=</mo><mn>1250</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> г</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">m=80\\cdot500\\cdot\\frac1{32}=\\frac{80}{32}\\cdot500=2{,}5\\cdot500=1250\\text{ г}.</annotation></semantics></math></p><p><strong>Ответ: 1250</strong></p>","5.2":"<p><strong>1)</strong> Площадь одного листа A1 равна\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mfrac><mn>1</mn><mn>2</mn></mfrac><annotation encoding=\"application/x-tex\">\\frac12</annotation></semantics></math>\nм².</p><p><strong>2)</strong> Сразу найдём массу всей пачки:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi><mo>=</mo><mn>120</mn><mo>⋅</mo><mn>80</mn><mo>⋅</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>=</mo><mn>60</mn><mo>⋅</mo><mn>80</mn><mo>=</mo><mn>4800</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> г</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">m=120\\cdot80\\cdot\\frac12=60\\cdot80=4800\\text{ г}.</annotation></semantics></math></p><p><strong>Ответ: 4800</strong></p>","5.3":"<p><strong>1)</strong> Листы A3 и A4 подобны. При переходе от A4 к A3\nлинейные размеры увеличиваются в\n<strong><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msqrt><mn>2</mn></msqrt><annotation encoding=\"application/x-tex\">\\sqrt{2}</annotation></semantics></math></strong>\nраза.</p><p><strong>2)</strong> Значит, высоту шрифта нужно тоже умножить на\n<strong><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msqrt><mn>2</mn></msqrt><annotation encoding=\"application/x-tex\">\\sqrt{2}</annotation></semantics></math></strong>:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>15</mn><mo>⋅</mo><msqrt><mn>2</mn></msqrt><mo>≈</mo><mn>15</mn><mo>⋅</mo><mn>1</mn><mo>,</mo><mn>414</mn><mo>≈</mo><mn>21</mn><mo>,</mo><mn>2</mn></mrow><annotation encoding=\"application/x-tex\">15\\cdot\\sqrt{2}\\approx 15\\cdot1{,}414\\approx21{,}2</annotation></semantics></math>.</p><p><strong>3)</strong> После округления получаем <strong>21</strong>\nпункт.</p><p><strong>Ответ: 21</strong></p>","5.4":"<p><strong>1)</strong> При переходе от A4 к A5 линейные размеры\nуменьшаются в\n<strong><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msqrt><mn>2</mn></msqrt><annotation encoding=\"application/x-tex\">\\sqrt{2}</annotation></semantics></math></strong>\nраза, то есть умножаются на\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mfrac><mn>1</mn><msqrt><mn>2</mn></msqrt></mfrac><annotation encoding=\"application/x-tex\">\\frac{1}{\\sqrt{2}}</annotation></semantics></math>.</p><p><strong>2)</strong> Получаем высоту шрифта:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>16</mn><mo>:</mo><msqrt><mn>2</mn></msqrt><mo>≈</mo><mn>16</mn><mo>:</mo><mn>1</mn><mo>,</mo><mn>414</mn><mo>≈</mo><mn>11</mn><mo>,</mo><mn>3</mn></mrow><annotation encoding=\"application/x-tex\">16: \\sqrt{2}\\approx16:1{,}414\\approx11{,}3</annotation></semantics></math>.</p><p><strong>3)</strong> После округления получаем <strong>11</strong>\nпунктов.</p><p><strong>Ответ: 11</strong></p>"},"plot":{"1.1":"<p><strong>1)</strong> В центре участка расположен\n<strong>цветник</strong>, на плане это объект <strong>4</strong>.</p><p><strong>2)</strong> Справа от единственных ворот расположен\n<strong>гараж</strong> — объект <strong>2</strong>.</p><p><strong>3)</strong> Напротив входа в дом находится\n<strong>беседка</strong> — объект <strong>5</strong>, а рядом с ней\nрасположен <strong>мангал</strong> — объект <strong>3</strong>.</p><p><strong>4)</strong> Записываем цифры в требуемом порядке: <strong>4,\n2, 3, 5</strong>.</p><p><strong>Ответ: 4235</strong></p>","1.2":"<p><strong>1)</strong> Напротив входа в жилой дом (объект 6) расположена\n<strong>беседка</strong>, значит, это объект <strong>5</strong>.</p><p><strong>2)</strong> Ели на плане отмечены возле объекта\n<strong>7</strong>.</p><p><strong>3)</strong> Справа от ворот расположен <strong>гараж</strong>\n— объект <strong>2</strong>.</p><p><strong>4)</strong> Рядом с беседкой находится\n<strong>мангал</strong> — объект <strong>3</strong>. Записываем:\n<strong>5723</strong>.</p><p><strong>Ответ: 5723</strong></p>","2.1":"<p><strong>1)</strong> Цветник занимает на плане <strong>8\nклеток</strong>.</p><p><strong>2)</strong> Сторона клетки равна 2 м, поэтому площадь одной\nклетки: 2·2=4 м².</p><p><strong>3)</strong> Площадь цветника: 8·4=32 м².</p><p><strong>Ответ: 32</strong></p>","2.2":"<p><strong>1)</strong> Жилой дом занимает <strong>21 целую клетку и две\nполовины клетки</strong>, то есть всего <strong>22 клетки</strong>.</p><p><strong>2)</strong> Площадь одной клетки: 2·2=4 м².</p><p><strong>3)</strong> Площадь дома: 22·4=88 м².</p><p><strong>Ответ: 88</strong></p>","3.1":"<p><strong>1)</strong> По плану на обе площадки и все дорожки требуется\n<strong>428 плиток</strong> размером 50×50 см.</p><p><strong>2)</strong> Площадь одной плитки: 0,5·0,5=0,25 м². В упаковке\nна 3,5 м² содержится 3,5:0,25=14 плиток.</p><p><strong>3)</strong> Получаем 428:14≈30,57. Нужное число упаковок\nокругляем вверх: <strong>31</strong>.</p><p><strong>Ответ: 31</strong></p>","3.2":"<p><strong>1)</strong> На дорожки требуется <strong>204\nплитки</strong>.</p><p><strong>2)</strong> В одной упаковке 8 плиток: 204:8=25,5.</p><p><strong>3)</strong> 25 упаковок не хватит, поэтому понадобится\n<strong>26 упаковок</strong>.</p><p><strong>Ответ: 26</strong></p>","4.1":"<p><strong>1)</strong> Участок имеет размеры <strong>15×10\nклеток</strong>, значит, его площадь равна 150 клеткам.</p><p><strong>2)</strong> Сарай занимает <strong>3×2=6 клеток</strong>.</p><p><strong>3)</strong> Доля сарая: 6:150·100%=4%.</p><p><strong>Ответ: 4</strong></p>","4.2":"<p><strong>1)</strong> Между ближайшими точками гаража и дома получается\nпрямоугольный треугольник с катетами <strong>3 и 4 клетки</strong>.</p><p><strong>2)</strong> По теореме Пифагора:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mrow><msup><mn>3</mn><mn>2</mn></msup><mo>+</mo><msup><mn>4</mn><mn>2</mn></msup></mrow></msqrt><mo>=</mo><mn>5</mn></mrow><annotation encoding=\"application/x-tex\">\\sqrt{3^2+4^2}=5</annotation></semantics></math>\nклеток.</p><p><strong>3)</strong> Одна клетка соответствует 2 м, поэтому расстояние\nравно 5·2=10 м.</p><p><strong>Ответ: 10</strong></p>","5.1":"<p><strong>1)</strong> Найдём, насколько газовое оборудование дороже\nэлектрического. Удобно вычесть соответствующие статьи затрат:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>28</mn><mspace width=\"0.167em\"></mspace><mn>000</mn><mo>−</mo><mn>22</mn><mspace width=\"0.167em\"></mspace><mn>000</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>+</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>16</mn><mspace width=\"0.167em\"></mspace><mn>540</mn><mo>−</mo><mn>14</mn><mspace width=\"0.167em\"></mspace><mn>444</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mn>6000</mn><mo>+</mo><mn>2096</mn><mo>=</mo><mn>8096</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">(28\\,000-22\\,000)+(16\\,540-14\\,444)=6000+2096=8096\\text{ руб.}</annotation></semantics></math><strong>2)</strong> Экономия за один час работы равна разности стоимости\nчаса электрического и газового отопления:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>5</mn><mo>,</mo><mn>8</mn><mo>⋅</mo><mn>4</mn><mo>,</mo><mn>4</mn><mo>−</mo><mn>1</mn><mo>,</mo><mn>1</mn><mo>⋅</mo><mn>4</mn><mo>,</mo><mn>8</mn><mo>=</mo><mn>25</mn><mo>,</mo><mn>52</mn><mo>−</mo><mn>5</mn><mo>,</mo><mn>28</mn><mo>=</mo><mn>20</mn><mo>,</mo><mn>24</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб./ч</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">5{,}8\\cdot4{,}4-1{,}1\\cdot4{,}8=25{,}52-5{,}28=20{,}24\\text{ руб./ч}.</annotation></semantics></math><strong>3)</strong> Время окупаемости:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>8096</mn><mrow><mn>20</mn><mo>,</mo><mn>24</mn></mrow></mfrac><mo>=</mo><mn>400</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> ч</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{8096}{20{,}24}=400\\text{ ч}.</annotation></semantics></math></p><p><strong>Ответ: 400</strong></p>","5.2":"<p><strong>1)</strong> Разность первоначальных затрат удобно получить по\nсоответствующим статьям:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>18</mn><mspace width=\"0.167em\"></mspace><mn>000</mn><mo>−</mo><mn>13</mn><mspace width=\"0.167em\"></mspace><mn>000</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>+</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>9980</mn><mo>−</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>500</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mn>5000</mn><mo>−</mo><mn>520</mn><mo>=</mo><mn>4480</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб.</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">(18\\,000-13\\,000)+(9980-10\\,500)=5000-520=4480\\text{ руб.}</annotation></semantics></math><strong>2)</strong> Экономия за один час:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>6</mn><mo>,</mo><mn>4</mn><mo>⋅</mo><mn>4</mn><mo>,</mo><mn>4</mn><mo>−</mo><mn>1</mn><mo>,</mo><mn>2</mn><mo>⋅</mo><mn>4</mn><mo>,</mo><mn>8</mn><mo>=</mo><mn>28</mn><mo>,</mo><mn>16</mn><mo>−</mo><mn>5</mn><mo>,</mo><mn>76</mn><mo>=</mo><mn>22</mn><mo>,</mo><mn>4</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> руб./ч</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">6{,}4\\cdot4{,}4-1{,}2\\cdot4{,}8=28{,}16-5{,}76=22{,}4\\text{ руб./ч}.</annotation></semantics></math><strong>3)</strong> Время окупаемости:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>4480</mn><mrow><mn>22</mn><mo>,</mo><mn>4</mn></mrow></mfrac><mo>=</mo><mn>200</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> ч</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{4480}{22{,}4}=200\\text{ ч}.</annotation></semantics></math></p><p><strong>Ответ: 200</strong></p>"},"villages":{"1.1":"<p><strong>1)</strong> По условию Антоновка — это цифра\n<strong>1</strong>. До Ванютино едут по верхнему шоссе, а там\nповорачивают налево на другое шоссе. Значит, <strong>Ванютино —\n4</strong>.</p><p><strong>2)</strong> От Егорки до Жилино идёт просёлочная дорога мимо\nконюшни. На плане такая дорога соединяет точки <strong>2</strong> и\n<strong>5</strong>, поэтому <strong>Егорка — 2</strong>, <strong>Жилино\n— 5</strong>.</p><p><strong>3)</strong> От Доломино до Горионово идёт просёлочная дорога\nмимо конюшни. Это точки <strong>3</strong> и <strong>6</strong>, значит\n<strong>Горионово — 6</strong>.</p><p><strong>4)</strong> Ответ в указанном порядке:\n<strong>4635</strong>.</p><p><strong>Ответ: 4635</strong></p>","1.2":"<p><strong>1)</strong> Ванютино — точка поворота двух шоссе, значит это\n<strong>4</strong>.</p><p><strong>2)</strong> Точка <strong>2</strong> соединена просёлочной\nдорогой с Жилино мимо конюшни, значит это <strong>Егорка</strong>.</p><p><strong>3)</strong> Тогда между Ванютино и Антоновкой остаётся\nдеревня <strong>Доломино</strong>, это цифра <strong>3</strong>.</p><p><strong>4)</strong> Жилино — точка <strong>5</strong>. Ответ:\n<strong>2435</strong>.</p><p><strong>Ответ: 2435</strong></p>","1.3":"<p><strong>1)</strong> Из Антоновки в Богданово можно проехать напрямую\nпо просёлочной дороге мимо реки. Такая дорога ведёт к нижней точке\n<strong>7</strong>, значит <strong>Богданово — 7</strong>.</p><p><strong>2)</strong> Горионово — точка <strong>6</strong>, потому что\nк ней идёт дорога от Доломино мимо конюшни и дорога от Антоновки мимо\nпруда.</p><p><strong>3)</strong> Доломино и Егорка — точки <strong>3</strong> и\n<strong>2</strong> на верхнем шоссе между Ванютино и Антоновкой. По\nусловию от Доломино до Егорки 4 км, а от Егорки до Ванютино 12 км,\nзначит ближе к Ванютино находится <strong>Егорка — 2</strong>, а\n<strong>Доломино — 3</strong>.</p><p><strong>Ответ: 7632</strong></p>","1.4":"<p><strong>1)</strong> Богданово — конечная точка прямой дороги из\nАнтоновки мимо реки, то есть <strong>7</strong>.</p><p><strong>2)</strong> Ванютино — поворот двух шоссе, это\n<strong>4</strong>.</p><p><strong>3)</strong> Егорка — точка <strong>2</strong>, так как из неё\nидёт дорога к Жилино мимо конюшни.</p><p><strong>4)</strong> Жилино — точка <strong>5</strong>. Ответ:\n<strong>7425</strong>.</p><p><strong>Ответ: 7425</strong></p>","2.1":"<p><strong>1)</strong> По условию от Ванютино до Жилино <strong>9\nкм</strong>, а от Жилино до Богданово <strong>12 км</strong>.</p><p><strong>2)</strong> Весь путь проходит по одному шоссе, поэтому\nрасстояние равно 9+12=21 км.</p><p><strong>Ответ: 21</strong></p>","2.2":"<p><strong>1)</strong> От Антоновки до Доломино <strong>12 км</strong>,\nот Доломино до Егорки <strong>4 км</strong>.</p><p><strong>2)</strong> Поэтому расстояние от Антоновки до Егорки равно\n12+4=16 км.</p><p><strong>Ответ: 16</strong></p>","2.3":"<p><strong>1)</strong> От Егорки до Ванютино <strong>12 км</strong>, а\nот Доломино до Егорки <strong>4 км</strong>.</p><p><strong>2)</strong> Значит, от Доломино до Ванютино остаётся 12−4=8\nкм.</p><p><strong>Ответ: 8</strong></p>","2.4":"<p><strong>1)</strong> От Ванютино до Горионово <strong>15 км</strong>,\nот Ванютино до Жилино <strong>9 км</strong>.</p><p><strong>2)</strong> Следовательно, между Горионово и Жилино по шоссе\n15−9=6 км.</p><p><strong>Ответ: 6</strong></p>","3.1":"<p><strong>1)</strong> От Егорки до Ванютино по шоссе <strong>12\nкм</strong>, от Ванютино до Жилино <strong>9 км</strong>.</p><p><strong>2)</strong> Просёлочная дорога образует прямоугольный\nтреугольник с катетами 12 км и 9 км.</p><p><strong>3)</strong> По теореме Пифагора:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mrow><msup><mn>12</mn><mn>2</mn></msup><mo>+</mo><msup><mn>9</mn><mn>2</mn></msup></mrow></msqrt><mo>=</mo><msqrt><mn>225</mn></msqrt><mo>=</mo><mn>15</mn></mrow><annotation encoding=\"application/x-tex\">\\sqrt{12^2+9^2}=\\sqrt{225}=15</annotation></semantics></math>\nкм.</p><p><strong>Ответ: 15</strong></p>","3.2":"<p><strong>1)</strong> От Доломино до Ванютино по шоссе <strong>8\nкм</strong>, от Ванютино до Горионово <strong>15 км</strong>.</p><p><strong>2)</strong> Просёлочная дорога Доломино–Горионово —\nгипотенуза прямоугольного треугольника с катетами 8 км и 15 км.</p><p><strong>3)</strong> По теореме Пифагора получаем\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mrow><msup><mn>8</mn><mn>2</mn></msup><mo>+</mo><msup><mn>15</mn><mn>2</mn></msup></mrow></msqrt><mo>=</mo><msqrt><mn>289</mn></msqrt><mo>=</mo><mn>17</mn></mrow><annotation encoding=\"application/x-tex\">\\sqrt{8^2+15^2}=\\sqrt{289}=17</annotation></semantics></math>\nкм.</p><p><strong>Ответ: 17</strong></p>","3.3":"<p><strong>1)</strong> От Ванютино до Антоновки по верхнему шоссе нужно\nпройти через Егорку и Доломино: 12+4+12=28 км.</p><p><strong>2)</strong> От Ванютино до Богданово по левому шоссе: 9+12=21\nкм.</p><p><strong>3)</strong> Просёлочная дорога Антоновка–Богданово —\nгипотенуза с катетами 28 км и 21 км. Тогда\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mrow><msup><mn>28</mn><mn>2</mn></msup><mo>+</mo><msup><mn>21</mn><mn>2</mn></msup></mrow></msqrt><mo>=</mo><msqrt><mn>1225</mn></msqrt><mo>=</mo><mn>35</mn></mrow><annotation encoding=\"application/x-tex\">\\sqrt{28^2+21^2}=\\sqrt{1225}=35</annotation></semantics></math>\nкм.</p><p><strong>Ответ: 35</strong></p>","4.1":"<p><strong>1)</strong> По шоссе проезжают\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>12</mn><mo>+</mo><mn>6</mn><mo>=</mo><mn>18</mn></mrow><annotation encoding=\"application/x-tex\">12+6=18</annotation></semantics></math>\nкм, по просёлочной дороге —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>17</mn><annotation encoding=\"application/x-tex\">17</annotation></semantics></math>\nкм. Сначала объединяем участки с одинаковой скоростью.</p><p><strong>2)</strong> Время в минутах:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>18</mn><mn>50</mn></mfrac><mo>⋅</mo><mn>60</mn><mo>+</mo><mfrac><mn>17</mn><mn>30</mn></mfrac><mo>⋅</mo><mn>60</mn><mo>=</mo><mn>21</mn><mo>,</mo><mn>6</mn><mo>+</mo><mn>34</mn><mo>=</mo><mn>55</mn><mo>,</mo><mn>6</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мин</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{18}{50}\\cdot60+\\frac{17}{30}\\cdot60=21{,}6+34=55{,}6\\text{ мин}.</annotation></semantics></math></p><p><strong>Ответ: 55,6</strong></p>","4.2":"<p><strong>1)</strong> По шоссе проезжают\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>16</mn><mo>+</mo><mn>12</mn><mo>=</mo><mn>28</mn></mrow><annotation encoding=\"application/x-tex\">16+12=28</annotation></semantics></math>\nкм, по просёлочной дороге —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>15</mn><annotation encoding=\"application/x-tex\">15</annotation></semantics></math>\nкм.</p><p><strong>2)</strong> Сразу считаем время по двум типам дорог:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>28</mn><mn>50</mn></mfrac><mo>⋅</mo><mn>60</mn><mo>+</mo><mfrac><mn>15</mn><mn>30</mn></mfrac><mo>⋅</mo><mn>60</mn><mo>=</mo><mn>33</mn><mo>,</mo><mn>6</mn><mo>+</mo><mn>30</mn><mo>=</mo><mn>63</mn><mo>,</mo><mn>6</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мин</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{28}{50}\\cdot60+\\frac{15}{30}\\cdot60=33{,}6+30=63{,}6\\text{ мин}.</annotation></semantics></math></p><p><strong>Ответ: 63,6</strong></p>","4.3":"<p><strong>1)</strong> Прямая просёлочная дорога Антоновка–Богданово\nимеет длину <strong>35 км</strong>.</p><p><strong>2)</strong> По просёлочной дороге едут со скоростью\n<strong>30 км/ч</strong>.</p><p><strong>3)</strong> Время равно\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mfrac><mn>35</mn><mn>30</mn></mfrac><annotation encoding=\"application/x-tex\">\\frac{35}{30}</annotation></semantics></math>\nч =\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mfrac><mn>7</mn><mn>6</mn></mfrac><annotation encoding=\"application/x-tex\">\\frac{7}{6}</annotation></semantics></math>\nч = <strong>70 минут</strong>.</p><p><strong>Ответ: 70</strong></p>","4.4":"<p><strong>1)</strong> От Антоновки до Ванютино по шоссе 12+4+12=28 км,\nот Ванютино до Богданово по шоссе <strong>21 км</strong>.</p><p><strong>2)</strong> Весь путь по шоссе: 28+21=49 км.</p><p><strong>3)</strong> Время:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mfrac><mn>49</mn><mn>50</mn></mfrac><annotation encoding=\"application/x-tex\">\\frac{49}{50}</annotation></semantics></math>\nч = 0,98·60=58,8 мин.</p><p><strong>Ответ: 58,8</strong></p>","5.1":"<p><strong>1)</strong> Через Ванютино весь путь проходит по шоссе и\nравен\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>49</mn><annotation encoding=\"application/x-tex\">49</annotation></semantics></math>\nкм. Во втором маршруте —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>18</mn><annotation encoding=\"application/x-tex\">18</annotation></semantics></math>\nкм по шоссе и\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>17</mn><annotation encoding=\"application/x-tex\">17</annotation></semantics></math>\nкм по просёлочной дороге. Пусть расход на просёлочной дороге равен\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x</mi><annotation encoding=\"application/x-tex\">x</annotation></semantics></math>\nл на 100 км.</p><p><strong>2)</strong> Составим равенство расходов и сразу сократим\nобщий знаменатель 100:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>49</mn><mo>⋅</mo><mn>6</mn><mo>,</mo><mn>8</mn><mo>=</mo><mn>18</mn><mo>⋅</mo><mn>6</mn><mo>,</mo><mn>8</mn><mo>+</mo><mn>17</mn><mi>x</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">49\\cdot6{,}8=18\\cdot6{,}8+17x.</annotation></semantics></math><strong>3)</strong> Не перемножаем большие числа заранее: сначала\nвыносим общий множитель\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>6</mn><mo>,</mo><mn>8</mn></mrow><annotation encoding=\"application/x-tex\">6{,}8</annotation></semantics></math>:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>17</mn><mi>x</mi><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>49</mn><mo>−</mo><mn>18</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>⋅</mo><mn>6</mn><mo>,</mo><mn>8</mn><mo>=</mo><mn>31</mn><mo>⋅</mo><mn>6</mn><mo>,</mo><mn>8</mn><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>x</mi><mo>=</mo><mfrac><mrow><mn>31</mn><mo>⋅</mo><mn>6</mn><mo>,</mo><mn>8</mn></mrow><mn>17</mn></mfrac><mo>=</mo><mn>12</mn><mo>,</mo><mn>4</mn><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">17x=(49-18)\\cdot6{,}8=31\\cdot6{,}8,\n\\qquad\nx=\\frac{31\\cdot6{,}8}{17}=12{,}4.</annotation></semantics></math></p><p><strong>Ответ: 12,4</strong></p>","5.2":"<p><strong>1)</strong> Через Ванютино путь по шоссе равен\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>49</mn><annotation encoding=\"application/x-tex\">49</annotation></semantics></math>\nкм, напрямую по просёлочной дороге —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>35</mn><annotation encoding=\"application/x-tex\">35</annotation></semantics></math>\nкм. Пусть расход на просёлочной дороге равен\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x</mi><annotation encoding=\"application/x-tex\">x</annotation></semantics></math>\nл на 100 км.</p><p><strong>2)</strong> После сокращения общего знаменателя 100 получаем\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>49</mn><mo>⋅</mo><mn>5</mn><mo>=</mo><mn>35</mn><mi>x</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">49\\cdot5=35x.</annotation></semantics></math><strong>3)</strong> Сначала сокращаем числа:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>49</mn><mn>35</mn></mfrac><mo>=</mo><mfrac><mn>7</mn><mn>5</mn></mfrac></mrow><annotation encoding=\"application/x-tex\">\\frac{49}{35}=\\frac75</annotation></semantics></math>,\nпоэтому\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi><mo>=</mo><mfrac><mrow><mn>49</mn><mo>⋅</mo><mn>5</mn></mrow><mn>35</mn></mfrac><mo>=</mo><mfrac><mn>7</mn><mn>5</mn></mfrac><mo>⋅</mo><mn>5</mn><mo>=</mo><mn>7</mn><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">x=\\frac{49\\cdot5}{35}=\\frac75\\cdot5=7.</annotation></semantics></math></p><p><strong>Ответ: 7</strong></p>","5.3":"<p><strong>1)</strong> Через Ванютино —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>49</mn><annotation encoding=\"application/x-tex\">49</annotation></semantics></math>\nкм по шоссе. Через Егорку и Жилино —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>28</mn><annotation encoding=\"application/x-tex\">28</annotation></semantics></math>\nкм по шоссе и\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>15</mn><annotation encoding=\"application/x-tex\">15</annotation></semantics></math>\nкм по просёлочной дороге. Пусть расход на просёлочной дороге равен\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x</mi><annotation encoding=\"application/x-tex\">x</annotation></semantics></math>\nл на 100 км.</p><p><strong>2)</strong> Сокращаем общий знаменатель 100 и переносим\nодинаковый расход по шоссе в одну часть:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>49</mn><mo>⋅</mo><mn>5</mn><mo>,</mo><mn>5</mn><mo>=</mo><mn>28</mn><mo>⋅</mo><mn>5</mn><mo>,</mo><mn>5</mn><mo>+</mo><mn>15</mn><mi>x</mi><mo>,</mo></mrow><annotation encoding=\"application/x-tex\">49\\cdot5{,}5=28\\cdot5{,}5+15x,</annotation></semantics></math><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>15</mn><mi>x</mi><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>49</mn><mo>−</mo><mn>28</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>⋅</mo><mn>5</mn><mo>,</mo><mn>5</mn><mo>=</mo><mn>21</mn><mo>⋅</mo><mn>5</mn><mo>,</mo><mn>5</mn><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">15x=(49-28)\\cdot5{,}5=21\\cdot5{,}5.</annotation></semantics></math><strong>3)</strong> Сначала сокращаем дробь\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>21</mn><mn>15</mn></mfrac><mo>=</mo><mfrac><mn>7</mn><mn>5</mn></mfrac></mrow><annotation encoding=\"application/x-tex\">\\frac{21}{15}=\\frac75</annotation></semantics></math>:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi><mo>=</mo><mfrac><mn>7</mn><mn>5</mn></mfrac><mo>⋅</mo><mn>5</mn><mo>,</mo><mn>5</mn><mo>=</mo><mn>7</mn><mo>,</mo><mn>7</mn><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">x=\\frac75\\cdot5{,}5=7{,}7.</annotation></semantics></math></p><p><strong>Ответ: 7,7</strong></p>","5.4":"<p><strong>1)</strong> Через Ванютино —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>49</mn><annotation encoding=\"application/x-tex\">49</annotation></semantics></math>\nкм по шоссе. Через Доломино и Горионово —\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>18</mn><annotation encoding=\"application/x-tex\">18</annotation></semantics></math>\nкм по шоссе и\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>17</mn><annotation encoding=\"application/x-tex\">17</annotation></semantics></math>\nкм по просёлочной дороге. Пусть расход на просёлочной дороге равен\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x</mi><annotation encoding=\"application/x-tex\">x</annotation></semantics></math>\nл на 100 км.</p><p><strong>2)</strong> После сокращения общего знаменателя 100:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>49</mn><mo>⋅</mo><mn>7</mn><mo>,</mo><mn>9</mn><mo>=</mo><mn>18</mn><mo>⋅</mo><mn>7</mn><mo>,</mo><mn>9</mn><mo>+</mo><mn>17</mn><mi>x</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">49\\cdot7{,}9=18\\cdot7{,}9+17x.</annotation></semantics></math><strong>3)</strong> Сначала вычтем одинаковую шоссейную часть, не\nраскрывая произведения:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>17</mn><mi>x</mi><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>49</mn><mo>−</mo><mn>18</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>⋅</mo><mn>7</mn><mo>,</mo><mn>9</mn><mo>=</mo><mn>31</mn><mo>⋅</mo><mn>7</mn><mo>,</mo><mn>9</mn><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>x</mi><mo>=</mo><mfrac><mrow><mn>31</mn><mo>⋅</mo><mn>7</mn><mo>,</mo><mn>9</mn></mrow><mn>17</mn></mfrac><mo>≈</mo><mn>14</mn><mo>,</mo><mn>4</mn><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">17x=(49-18)\\cdot7{,}9=31\\cdot7{,}9,\n\\qquad\nx=\\frac{31\\cdot7{,}9}{17}\\approx14{,}4.</annotation></semantics></math></p><p><strong>Ответ: 14,4</strong></p>"}};

    const TIRE_SCENARIO_SOLUTIONS = {"tires-plot-1":{"4":"<p><strong>1)</strong> Не будем отдельно вычислять два полных диаметра.\nСразу запишем их разность:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>20</mn><mo>−</mo><mn>18</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>⋅</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>+</mo><mn>2</mn><mo minsize=\"1.2\" maxsize=\"1.2\" stretchy=\"false\" form=\"prefix\">(</mo><mn>265</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>35</mn><mo>−</mo><mn>245</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>45</mn><mo minsize=\"1.2\" maxsize=\"1.2\" stretchy=\"false\" form=\"postfix\">)</mo><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=(20-18)\\cdot25{,}4+2\\bigl(265\\cdot0{,}35-245\\cdot0{,}45\\bigr).</annotation></semantics></math><strong>2)</strong> Сначала упростим выражение:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mn>2</mn><mo>⋅</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>+</mo><mn>2</mn><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>92</mn><mo>,</mo><mn>75</mn><mo>−</mo><mn>110</mn><mo>,</mo><mn>25</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mn>50</mn><mo>,</mo><mn>8</mn><mo>−</mo><mn>35</mn><mo>=</mo><mn>15</mn><mo>,</mo><mn>8</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мм</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=2\\cdot25{,}4+2(92{,}75-110{,}25)=50{,}8-35=15{,}8\\text{ мм}.</annotation></semantics></math></p><p><strong>Ответ: 15,8</strong></p>","5":"<p><strong>1)</strong> За один оборот колесо проходит длину окружности\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mi>π</mi><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">L=\\pi D</annotation></semantics></math>,\nпоэтому процентное изменение пробега равно процентному изменению\nдиаметра: множитель\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>π</mi><annotation encoding=\"application/x-tex\">\\pi</annotation></semantics></math>\nсокращается. <strong>2)</strong> Диаметр диска и профиль\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>45</mn><mi>%</mi></mrow><annotation encoding=\"application/x-tex\">45\\%</annotation></semantics></math>\nодинаковы. В разности диаметров общая часть сокращается:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mn>2</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>45</mn><mspace width=\"0.167em\"></mspace><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>265</mn><mo>−</mo><mn>245</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mn>0</mn><mo>,</mo><mn>9</mn><mo>⋅</mo><mn>20</mn><mo>=</mo><mn>18</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мм</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=2\\cdot0{,}45\\,(265-245)=0{,}9\\cdot20=18\\text{ мм}.</annotation></semantics></math><strong>3)</strong> Исходный диаметр\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D</mi><mn>0</mn></msub><mo>=</mo><mn>677</mn><mo>,</mo><mn>7</mn></mrow><annotation encoding=\"application/x-tex\">D_0=677{,}7</annotation></semantics></math>\nмм, поэтому\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>18</mn><mrow><mn>677</mn><mo>,</mo><mn>7</mn></mrow></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>≈</mo><mn>2</mn><mo>,</mo><mn>7</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{18}{677{,}7}\\cdot100\\%\\approx2{,}7\\%.</annotation></semantics></math></p><p><strong>Ответ: 2,7</strong></p>"},"tires-plot-2":{"4":"<p><strong>1)</strong> Сразу найдём разность диаметров, не вычисляя\nкаждый диаметр полностью:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>17</mn><mo>−</mo><mn>16</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>⋅</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>+</mo><mn>2</mn><mo minsize=\"1.2\" maxsize=\"1.2\" stretchy=\"false\" form=\"prefix\">(</mo><mn>225</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>45</mn><mo>−</mo><mn>205</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>55</mn><mo minsize=\"1.2\" maxsize=\"1.2\" stretchy=\"false\" form=\"postfix\">)</mo><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=(17-16)\\cdot25{,}4+2\\bigl(225\\cdot0{,}45-205\\cdot0{,}55\\bigr).</annotation></semantics></math><strong>2)</strong> Упростим:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>+</mo><mn>2</mn><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>101</mn><mo>,</mo><mn>25</mn><mo>−</mo><mn>112</mn><mo>,</mo><mn>75</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>−</mo><mn>23</mn><mo>=</mo><mn>2</mn><mo>,</mo><mn>4</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мм</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=25{,}4+2(101{,}25-112{,}75)=25{,}4-23=2{,}4\\text{ мм}.</annotation></semantics></math></p><p><strong>Ответ: 2,4</strong></p>","5":"<p><strong>1)</strong> Длина окружности\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mi>π</mi><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">L=\\pi D</annotation></semantics></math>,\nпоэтому сравниваем диаметры:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>π</mi><annotation encoding=\"application/x-tex\">\\pi</annotation></semantics></math>\nсокращается. <strong>2)</strong> Диск и профиль\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>55</mn><mi>%</mi></mrow><annotation encoding=\"application/x-tex\">55\\%</annotation></semantics></math>\nодинаковы, значит\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mn>2</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>55</mn><mspace width=\"0.167em\"></mspace><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>215</mn><mo>−</mo><mn>205</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mn>1</mn><mo>,</mo><mn>1</mn><mo>⋅</mo><mn>10</mn><mo>=</mo><mn>11</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мм</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=2\\cdot0{,}55\\,(215-205)=1{,}1\\cdot10=11\\text{ мм}.</annotation></semantics></math><strong>3)</strong> Исходный диаметр\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D</mi><mn>0</mn></msub><mo>=</mo><mn>631</mn><mo>,</mo><mn>9</mn></mrow><annotation encoding=\"application/x-tex\">D_0=631{,}9</annotation></semantics></math>\nмм. Тогда\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>11</mn><mrow><mn>631</mn><mo>,</mo><mn>9</mn></mrow></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>≈</mo><mn>1</mn><mo>,</mo><mn>7</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{11}{631{,}9}\\cdot100\\%\\approx1{,}7\\%.</annotation></semantics></math></p><p><strong>Ответ: 1,7</strong></p>"},"tires-plot-3":{"4":"<p><strong>1)</strong> Сразу запишем разность диаметров:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>15</mn><mo>−</mo><mn>14</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>⋅</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>+</mo><mn>2</mn><mo minsize=\"1.2\" maxsize=\"1.2\" stretchy=\"false\" form=\"prefix\">(</mo><mn>195</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>55</mn><mo>−</mo><mn>185</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>60</mn><mo minsize=\"1.2\" maxsize=\"1.2\" stretchy=\"false\" form=\"postfix\">)</mo><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=(15-14)\\cdot25{,}4+2\\bigl(195\\cdot0{,}55-185\\cdot0{,}60\\bigr).</annotation></semantics></math><strong>2)</strong> Упростим выражение:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>+</mo><mn>2</mn><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>107</mn><mo>,</mo><mn>25</mn><mo>−</mo><mn>111</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>−</mo><mn>7</mn><mo>,</mo><mn>5</mn><mo>=</mo><mn>17</mn><mo>,</mo><mn>9</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мм</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=25{,}4+2(107{,}25-111)=25{,}4-7{,}5=17{,}9\\text{ мм}.</annotation></semantics></math></p><p><strong>Ответ: 17,9</strong></p>","5":"<p><strong>1)</strong> Процент изменения длины окружности равен проценту\nизменения диаметра, потому что в\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mi>π</mi><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">L=\\pi D</annotation></semantics></math>\nмножитель\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>π</mi><annotation encoding=\"application/x-tex\">\\pi</annotation></semantics></math>\nсокращается. <strong>2)</strong> Разность диаметров удобнее найти сразу:\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>16</mn><mo>−</mo><mn>14</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>⋅</mo><mn>25</mn><mo>,</mo><mn>4</mn><mo>+</mo><mn>2</mn><mo minsize=\"1.2\" maxsize=\"1.2\" stretchy=\"false\" form=\"prefix\">(</mo><mn>205</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>50</mn><mo>−</mo><mn>185</mn><mo>⋅</mo><mn>0</mn><mo>,</mo><mn>60</mn><mo minsize=\"1.2\" maxsize=\"1.2\" stretchy=\"false\" form=\"postfix\">)</mo><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=(16-14)\\cdot25{,}4+2\\bigl(205\\cdot0{,}50-185\\cdot0{,}60\\bigr).</annotation></semantics></math><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>D</mi><mo>=</mo><mn>50</mn><mo>,</mo><mn>8</mn><mo>+</mo><mn>2</mn><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>102</mn><mo>,</mo><mn>5</mn><mo>−</mo><mn>111</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mn>50</mn><mo>,</mo><mn>8</mn><mo>−</mo><mn>17</mn><mo>=</mo><mn>33</mn><mo>,</mo><mn>8</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> мм</mtext></mrow><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta D=50{,}8+2(102{,}5-111)=50{,}8-17=33{,}8\\text{ мм}.</annotation></semantics></math><strong>3)</strong> Исходный диаметр\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D</mi><mn>0</mn></msub><mo>=</mo><mn>577</mn><mo>,</mo><mn>6</mn></mrow><annotation encoding=\"application/x-tex\">D_0=577{,}6</annotation></semantics></math>\nмм, поэтому\n<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mn>33</mn><mo>,</mo><mn>8</mn></mrow><mrow><mn>577</mn><mo>,</mo><mn>6</mn></mrow></mfrac><mo>⋅</mo><mn>100</mn><mi>%</mi><mo>≈</mo><mn>5</mn><mo>,</mo><mn>9</mn><mi>%</mi><mi>.</mi></mrow><annotation encoding=\"application/x-tex\">\\frac{33{,}8}{577{,}6}\\cdot100\\%\\approx5{,}9\\%.</annotation></semantics></math></p><p><strong>Ответ: 5,9</strong></p>"}};

    const db = window.ogePracticeDatabase || {};

    Object.entries(FINAL_SOLUTIONS).forEach(([themeId, byPrototype]) => {
        const theme = db[themeId];
        if (!theme) return;

        const prototypes = (theme.catalog && Array.isArray(theme.catalog.prototypes))
            ? theme.catalog.prototypes
            : [];

        prototypes.forEach(proto => {
            const id = String(proto.id || proto.typeId || '');
            if (byPrototype[id]) proto.solution = byPrototype[id];
        });

        // В совпадающих сюжетах id задания совпадает с id каталожного прототипа.
        // Сюжеты с собственными id (например, другие участки) здесь намеренно не
        // подменяются чужими числами и условиями.
        (theme.scenarios || []).forEach(scenario => {
            Object.values(scenario.tasks || {}).forEach(group => {
                (group || []).forEach(task => {
                    const id = String(task.id || '');
                    if (id && byPrototype[id]) task.solution = byPrototype[id];
                });
            });
        });
    });

    // У шин три самостоятельных сюжета. Для заданий 4–5 решения переписаны
    // отдельно: сначала сокращаем общие части формулы, затем подставляем числа.
    const tireTheme = db.tires;
    if (tireTheme) {
        (tireTheme.scenarios || []).forEach(scenario => {
            const byTask = TIRE_SCENARIO_SOLUTIONS[String(scenario.id || '')];
            if (!byTask) return;
            Object.values(scenario.tasks || {}).forEach(group => {
                (group || []).forEach(task => {
                    const id = String(task.id || task.typeId || '');
                    if (byTask[id]) task.solution = byTask[id];
                });
            });
        });
    }
})();
